programs.sol:
"""Approximate local ampersand and escape-syntax responses.

Give a large positive value to the 1 after shell >& redirection. Give
negative values to numeric HTML quotation/hex escapes and split entity
names, with separate small rules for degree and copyright entities.
Rust references and bit masks are positive; and/or is negative. Otherwise
return zero, except for a small negative document-start offset.
"""
import unicodedata
from html.entities import name2codepoint

READS = ()
QUOTE_NAMES = {
    name for name, code in name2codepoint.items()
    if chr(code) in "\"'" or unicodedata.category(chr(code)) in ('Pi', 'Pf')
}
QUOTE_STARTS = {
    name[:i] for name in QUOTE_NAMES for i in range(2, len(name))
}


def step(carry, prefix, upstream):
    s = prefix.token_strings[-1]
    docs = prefix.document_ids
    same = len(docs) > 1 and docs[-1] == docs[-2]
    p = prefix.token_strings[-2] if same else ''
    pp = (prefix.token_strings[-3]
          if len(docs) > 2 and docs[-1] == docs[-3] else '')
    value = 0.0

    if not same:
        # A modest negative offset when there is no preceding context.
        value = -0.3 if s.strip().isalnum() else -0.12
    elif p.endswith('>&') and s == '1':
        value = 9.2
    elif s == '>&':
        value = -0.45
    elif p.endswith('&#'):
        if s == '3':               # beginning of &#34; or &#39;
            value = -6.6
        elif s == 'x':             # hexadecimal character escape
            value = -13.0
    elif pp.endswith('&#') and p == '3' and s in ('4', '9'):
        value = -3.5
    elif p + s in QUOTE_NAMES and p in QUOTE_STARTS:
        value = -6.5
    elif p.strip() == 'n' and s in ('bs', 'bsp'):
        # Split nonbreaking-space entity names, sometimes lacking their &.
        value = -12.0 if s == 'bs' else -8.0
    elif p.endswith('&') and not p.endswith('&&'):
        if s == 'mut':
            value = 2.4
        elif s == 'str':
            value = 3.5
        elif s == 'self':
            value = 0.7
        elif s.lstrip().startswith('~'):
            value = 5.0
        elif s == '-':
            value = 4.0
        elif s in QUOTE_NAMES:
            value = -1.0
        elif s in QUOTE_STARTS:
            value = -7.0
        elif s == 'frac':          # fractional-number entities
            value = -10.0
        elif s == 'deg':
            value = -2.7
        elif s == 'copy':
            value = 1.1
    elif s == '/or' and p.strip().lower() == 'and':
        value = -1.4
    return None, value

programs.haiku:
"""Component layers.1.mlp.down_proj:768: a detector for the token just after an ampersand.

The ampersand's use sets the sign:
  * shell stderr redirect "2>&1": the "1" is strongly positive (about +9);
  * HTML character references, which are negative: the first digit of
    "&#39;" or "&#34;" (about -6.6), the second digit (about -3.3), the "x" of
    a hex reference "&#x" (about -10), and the "n" / "bsp" of "&nbsp;"
    (about -3 and -8);
  * Rust / C reference and operator uses, "&mut", "&str", "&-", "&~":
    mildly positive (about +2.5);
  * the phrase "and/or": "/or" after "and" (about -1.4);
  * chemistry placeholders "##STR80##": "STR" (about -2.8).
Every other token predicts 0.
"""

READS = ()

DIGITS = set("0123456789")
AMP = ("&", " &", "(&", '"&', "'&", "<&", ">&")
CODE_AMP = ("mut", "str", "-", "~", " ~", "(~")


def step(carry, prefix, upstream):
    toks = prefix.token_strings
    cur = toks[-1]
    prev = toks[-2] if len(prefix) > 1 else ""
    prev2 = toks[-3] if len(prefix) > 2 else ""
    value = 0.0
    if cur == "1" and prev.endswith(">&"):
        value = 9.3
    elif prev.endswith("&#") and cur in DIGITS:
        value = -6.6
    elif prev.endswith("&#") and cur == "x":
        value = -10.0
    elif prev2.endswith("&#") and prev in DIGITS and cur in DIGITS:
        value = -3.3
    elif cur == "bsp" and prev.strip() == "n":
        value = -8.0
    elif cur == "n" and prev in AMP:
        value = -3.0
    elif prev in AMP and cur in CODE_AMP:
        value = 2.5
    elif cur == "/or" and prev.strip() == "and":
        value = -1.4
    elif cur == "STR" and prev.endswith("##"):
        value = -2.8
    return carry, value

programs.sol:
"""A token-boundary-sensitive dust signal, with local spelling side responses.

Literal dust is strongly positive, dirt weaker; dirty is zero, so this is
not a general uncleanliness classifier. Dust continuations can span tokens,
and Chinese dust characters give similar positive responses. Other rules
capture selected d/д/د continuations, Japanese kana endings, and Thai ดู.
Only the current token, previous token and an inherited previous response
are used. A new document clears this context.
"""
from functools import lru_cache
import regex
from anyascii import anyascii
import opencc

READS = ()
_SIMPLIFY = opencc.OpenCC('t2s')
_LATIN = regex.compile(r'\A\p{Script=Latin}+\Z')
_HAN = regex.compile(r'\p{Script=Han}')


@lru_cache(maxsize=131072)
def spelling(s):
    if s.isascii():
        return s.lower(), s
    roman = anyascii(s).lower() if _LATIN.fullmatch(s) else ''
    han = _SIMPLIFY.convert(s) if _HAN.search(s) else s
    return roman, han


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    prev, old_value = '', 0.0
    if carry is not None and carry[0] == doc:
        prev, old_value = carry[1:]
    s = prefix.token_strings[-1]
    word = s.strip().lower()
    roman, han = spelling(s)
    value = 0.0

    if '尘' in han:
        value = 8.5 if han == '尘' else 6.0
    elif prev.endswith(('尘', '塵')) and s in ('埃', '土'):
        value = 10.0 if s == '埃' else 6.3
    if word == 'dust':
        value = 10.1
    elif word == 'dusty':
        value = 7.2
    elif word == 'dirt':
        value = 4.1
    elif word == 'dus':
        value = 3.0
    elif prev.strip().lower() == 'dust':
        if s == 'ing':
            value = 8.7
        elif s == 's':
            value = 6.9
        elif s == 'an':
            value = 4.4
        elif s == ' of':
            value = 5.0
    elif roman and s.isalpha() and prev.endswith(('d', 'D')):
        separate_d = regex.search(r'(?:^|[^a-zA-Z])[dD]$', prev)
        strength = 1.0 if separate_d else 0.5
        if roman == 'ust':
            value = 10.0 if separate_d else 4.0
        elif separate_d and roman in ('usting', 'usty', 'uster'):
            value = 10.0
        elif separate_d and roman == 'ustin':
            value = 5.0
        elif roman == 'irt':
            value = 4.1
        elif roman == 'ask':
            value = 5.0 * strength
        elif roman == 'usk':
            value = 5.0 * strength
        elif roman == 'unk':
            value = 3.0 * strength
        elif roman in ('st', 'us', 'ost', 'ung'):
            value = 2.6 * strength
        if roman in ('ail', 'au', 'auer'):
            value = -3.2 * strength
        elif roman in ('ur', 'ure', 'ura', 'uring', 'ou', 'outh',
                       'ouch', 'ach', 'em', 'uch'):
            value = -2.1 * strength
        elif roman in ('ame', 'ameron'):
            value = -4.0 * strength
    # Cyrillic d endings, including split affricates.
    elif prev.endswith(('д', 'Д')):
        letters = sum(c.isalpha() for c in prev)
        strength = min(1.0, 2.0 / max(letters, 1))
        if s.startswith('аж'):
            value = -7.0 * strength
        elif s.startswith('ач'):
            value = -3.0
        elif s.startswith('руж'):
            value = -5.4 * strength
        elif s.startswith(('уж', 'уч', 'ур', 'ума')):
            value = -3.0 * strength
            if s == 'уч' and prev.lower().endswith('буд'):
                value = -4.0
        elif s.startswith('ост'):
            value = 0.8 * strength
    elif s in ('е', 'а', 'и') and old_value < -1:
        if prev == 'аж':
            value = (0.85 if s == 'е' else 0.4) * old_value
        elif prev == 'ач':
            value = 0.4 * old_value
        elif prev == 'уч':
            value = old_value
    elif prev.endswith(('да', 'Да')) and s.startswith(('ч', 'Ч')):
        value = -3.0
    elif prev.endswith('د') and s == 'ست':
        value = 3.1

    # Japanese conditional, list, and question continuations.
    if prev.endswith(('た', 'だ')):
        if s in ('ら', 'らい'):
            value = -6.6 if s == 'ら' else -5.0
        elif s in ('り', 'か', 'い', 'め', 'れ'):
            value = -4.0 if s == 'れ' else -2.9
            if prev.endswith('んだ') and s == 'か':
                value = -8.5
    elif prev.endswith(('す', 'ず', 'く')) and s in ('ら', 'らい'):
        value = -2.2
    if prev.endswith('ด') and s == 'ู':
        value = -4.0
    return (doc, s, value), value

programs.haiku:
"""Layer-1 MLP component 770 (down_proj): a document-opening detector.

Inside a document this component is almost silent. Nearly all of its activity sits on the
first token of each document (the first token of a packed row, or the first token after a
document break), where there is no earlier text to lean on. There it is signed by what
kind of word or symbol opens the text:

- foreign-language words (accented Latin letters, or common French/Spanish/Portuguese/
  Italian/German/Scandinavian function words) are strongly negative;
- non-Latin scripts (Cyrillic, Arabic, Kana, Greek, ...) are negative;
- short lowercase fragments with no leading space (pieces of a longer word) are negative,
  more so than short words after a space;
- longer English-looking words are near zero or slightly positive;
- code and quote openers (a double quote, a triple-quote line, comment starts, backticks)
  are positive;
- special tokens, digits and punctuation are mildly negative.

Everywhere else the prediction is 0.
"""

READS = ()

FOREIGN = set(
    """de la el que en y se su os do da das dos di du des le les une un und der die ist
    ein eine con por para una lo los las del al es che non um uma je il est qui ce sur mit
    auf ich er sie nicht zu och av som jest nie este esta esto ese esa son muy pero como
    más mas también cuando donde todo toda todos hay ser estar tiene tem era fue ha han
    sido entre sobre desde hasta porque aquí así nos vos sus mi tu ou não são foi já mais
    pelo pela pelos pelas até isso isto ele ela eles elas você nós une sont avec pour dans
    par plus mais donc car ni ne pas tout tous cette ces ses leur leurs nous vous ils elles
    être avoir fait comme aussi très bien della dei degli nella nel gli anche questo
    questa molto più ed è perché den dem des oder aber auch nicht einer eines sich wir ihr
    sind von für bei nach aus über durch wenn wie noch schon att det som för med är inte
    jag på till vi han hon eller om""".split()
)
CODE_OPENERS = {'"', '"""\n', "'''\n", '/*\n', '`', '[', '//', '//\n', '__', '#![', '@', '---\n'}


def first_token_value(s):
    """The activation predicted for a document's first token, from its decoded string."""
    if s.startswith("<|"):
        return -3.0  # special tokens such as <|im_start|>
    core = s.lstrip(" ")
    if core == "":
        return -0.6  # a bare space
    if "�" in s:
        return -3.0  # part of a multi-byte character
    if not core.isascii():
        letters = [c for c in core if c.isalpha()]
        if not letters:
            return -0.8
        if all(ord(c) < 0x250 for c in letters):
            return -12.0  # Latin letters with accents: foreign text
        if all("一" <= c <= "鿿" for c in letters):
            return -0.7  # Chinese characters
        return -7.0  # Cyrillic, Arabic, Kana, Greek, ...
    if core.isalpha():
        if core.lower() in FOREIGN:
            return -10.0
        spaced = s.startswith(" ")
        lower = core[0].islower()
        if len(core) <= 3:  # short pieces: mostly word fragments or function words
            if lower and not spaced:
                return -5.0
            return -1.8
        if len(core) <= 6:
            if lower:
                return -0.7 if spaced else -3.3
            return -0.3
        return 0.6  # long words read as ordinary English content
    if core.isdigit():
        return -1.0
    if s in CODE_OPENERS:
        return 3.0
    return -0.4


def step(carry, prefix, upstream):
    docs = prefix.document_ids
    starts_document = len(docs) == 1 or docs[-1] != docs[-2]
    if not starts_document:
        return None, 0.0
    return None, float(first_token_value(prefix.token_strings[-1]))

programs.sol:
"""A document-opening pulse, strongest for source-file opening syntax.

The signal persists if the opening token repeats, and otherwise switches off
as soon as a different token supplies context. Pulse sizes distinguish words,
separators, whitespace, and familiar code/documentation openings. This is a
coarse description: it omits fine lexical differences and later contextual noise.
"""
import regex
from wordfreq import zipf_frequency

READS = ()

SOURCE_DECLARATIONS = {
    'import', 'using', 'namespace', 'module', 'class', 'function',
    'const', 'let', 'var', 'public', 'private', 'protected', 'static',
    'int', 'void', 'export', 'type', 'interface', 'struct', 'enum',
}
DELIMITERS = set('.,:;!?()[]{}"\'，。；：！？、')


def opening_value(text):
    s = text.strip()
    if text.startswith('<|'):
        return -6.1
    if not s:
        if '\n' in text or '\r' in text:
            return -2.6
        return -0.5 if text in {' ', '\t'} else -3.6
    if not text[0].isspace():
        if s == 'package':                 # Java/Go package declaration
            return -31.4
        if s in {'def', 'from'}:           # Python definition/import opening
            return -22.0
        if s in SOURCE_DECLARATIONS:
            return -10.9
        if s.startswith(('"""', "'''")):
            return -16.4
        if set(s) == {'#'}:              # Markdown heading/comment marker
            return -14.0 if len(s) == 1 else -11.4 if len(s) == 2 else -6.0
        if s.startswith(('/*', '//')):
            return -8.5
        if s.startswith('#'):
            return -5.6
    if s.isdecimal():
        return -0.1 if not s.strip('0') else -2.8
    if not any(c.isalnum() for c in s):
        if set(s) <= DELIMITERS:
            return -1.6
        return -4.8 if len(s) > 1 and len(set(s)) == 1 else -2.5
    for script, value in [('Han', -3.1), ('Cyrillic', -5.3),
                          ('Hangul', -5.8), ('Arabic', -3.8)]:
        if regex.search(r'\p{Script=' + script + '}', s):
            return value
    if regex.search(r'\p{Script=Latin}', s):
        if zipf_frequency(s, 'en') >= 6:
            return -3.5
        return -4.3 if text[0].isspace() else -4.8
    return -3.7


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_ids[-1]
    if carry is None or carry[0] != doc:
        opening = True
    else:
        opening = carry[2] and token == carry[1]
    value = opening_value(prefix.token_strings[-1]) if opening else 0.0
    return (doc, token, opening), value

"""A sparse approximation using procedural grammar and document headers.

Positive cues are checking/comparing, step sequencing, and Chinese future or
means-of-action constructions. Reporting passives and emphatic or uncertain
adverbs are negative.
Unrecognized text stays near zero; small token-specific fluctuations are omitted.
"""
import re
from functools import lru_cache
import wordnet

READS = ()
SUBJECTS = set('i we it you they he she which that'.split())
MODALS = set('will would can could may might must should'.split())
PRESENT_BE = {'is', 'are', 'be'}
PROCEDURAL = set('check compare iterate compute calculate generate convert analyze'.split())

@lru_cache(maxsize=16384)
def roots(word):
    if word.isascii() and word.isalpha():
        return frozenset(wordnet.base_forms(word))
    return frozenset()


def step(carry, prefix, upstream):
    new = (prefix.position == 0 or
           prefix.document_ids[-1] != prefix.document_ids[-2])
    age = 0 if new else carry + 1
    s = prefix.token_strings[-1]
    prev = '' if new else prefix.token_strings[-2]
    w, p = s.strip().lower(), prev.strip().lower()
    r = roots(w)
    value = 0.0

    # Grammatical cues in ordinary English words, not code-name fragments.
    if s.startswith(' ') and w.isascii() and w.isalpha():
        if 'check' in r:
            value += 0.06
        if 'compare' in r:
            value += 0.05
        if r & {'check', 'compare'} and w.endswith('s'):
            value += 0.17
        if 'check' in r and p == 'me':
            value = -0.05
        if 'iterate' in r:
            value += 0.12
        if r & PROCEDURAL:
            if p in SUBJECTS:
                value += 0.30
            if p in MODALS or p in {'first', 'then', 'simply'}:
                value += 0.20
            if p == 'by' or p in PRESENT_BE:
                value += 0.20
        if w in {'first', 'then'}:
            if p in PRESENT_BE or p in SUBJECTS or p in MODALS:
                value += 0.23
            elif p in {'to', 'by'}:
                value += 0.13
            elif w == 'then' and p in {',', 'and', 'but'}:
                value -= 0.03
        if w == 'by' and p in {'work', 'works'}:
            value += 0.30
        if p == 'by' and w.endswith('ing'):
            value += 0.10
        if w == 'heated':
            value += 0.23
        if w in {'described', 'reported'}:
            value -= 0.10
            if p in {'is', 'are', 'as'}:
                value -= 0.10
        if w in {'certainly', 'definitely', 'absolutely'}:
            value -= 0.13
        if w in {'maybe', 'perhaps', 'apparently'}:
            value -= 0.07
        if w in {'the', 'a', 'an', 'it'} and roots(p) & PROCEDURAL:
            value += 0.10

    if s in {'会', '會'}:
        value += 0.08 if s == '会' else 0.18
        if prev in {'，', ','}:
            value += 0.26
        # The consequence of a temporal clause: 'when ... , [it] will ...'.
        tail = ''.join(prefix.token_strings[prefix.position-min(age, 4):
                                            prefix.position])
        if prev in {'后', '後'} or re.search('[时時]，[它他她]?$', tail):
            value = 0.72
    if s in {'将', '將'} and prev in {'会', '會', '是'}:
        value += 0.40
    if s in {'通过', '通過', '利用'} and prev == '是':
        value += 0.25
    if s == '章' and re.fullmatch('[零〇一二三四五六七八九十百千万兩两0-9]+', p):
        value -= 0.50

    # Strong, separate responses to common document-header conventions.
    if age == 0:
        if s == '<|im_start|>':
            value = 0.146
        if s.strip() and set(s.strip()) == {'#'}:
            value = -0.41
        if s == 'Title':
            value = -0.248
    if age == 1 and prev == 'Title' and s == ':':
        value = -1.464
    if prev == '<|im_start|>':
        if s == 'user':
            value = 0.042
        if s == 'assistant':
            value = -0.046
    if age < 10 and prev == '><' and s == 'issue':
        value = -0.603
    return age, value

programs.haiku:
"""layers.1.mlp.down_proj:772 - a weak, mostly token-driven unit.

What it does, in plain terms:
  * Most of the time it is near zero. Its variance is spread over many tokens and
    is not explained by any simple word class (nouns, verbs, function words, digits
    and punctuation all average to about zero).
  * Its clearest response is at the FIRST token of a document (where the document
    id changes, or the row starts). There the model has no earlier context, so the
    response is a fixed function of the token itself:
      - '#', '##', 'package' (code / markup openers)      -> strongly negative
      - newline, 'I', 'import', 'The', '<|im_start|>'     -> positive
      - a digit                                           -> mildly negative
  * Elsewhere, a few word families nudge it:
      - hedging adverbs (maybe, certainly, perhaps, ...)  -> mildly negative
      - 'deliver' / 'delivery' family                     -> mildly negative
      - Chinese 'will' (会, 會, 就会, 都会)                -> positive
      - 'check' / 'compare' verbs (checks, comparing, ...) -> mildly positive

The predictions are small in size, so this program explains only a sliver of the
variance (about 1 percent on held-out rows). A per-token lookup table fitted to
the same data would explain about 16 percent, but needs over 10,000 entries and
has no concept behind it, so it is not used here.
"""

READS = ()

DOC_START_NEGATIVE = {"#", "##", "package", "int", "Int", "char", "class", "string", "<?", '{"', '\\"', "path"}
DOC_START_POSITIVE = {"\n", "I", "We", "import", "The", "<|im_start|>", ",", ";"}
HEDGES = {
    "maybe", "perhaps", "certainly", "absolutely", "perfectly", "potentially",
    "probably", "possibly", "unlikely", "honestly", "definitely", "surely",
    "somebody", "nobody", "nowhere",
}
DELIVER = {"deliver", "delivers", "delivered", "delivering", "delivery"}
WILL_ZH = {"会", "會", "就会", "都会"}
CHECK = {"check", "checks", "checking", "compare", "compares", "comparing", "compared"}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1]
    key = word.strip().lower()
    starts_document = prefix.position == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]
    value = 0.0
    if starts_document:
        if word in DOC_START_NEGATIVE:
            value = -0.45
        elif word in DOC_START_POSITIVE:
            value = 0.25
        elif word.isdigit():
            value = -0.12
    elif key in HEDGES:
        value = -0.08
    elif key in DELIVER:
        value = -0.11
    elif key in WILL_ZH:
        value = 0.12
    elif key in CHECK:
        value = 0.08
    return carry, float(value)

programs.sol:
"""Detect language that introduces an example, illustration, or hypothetical case.

This is a local phrase heuristic, not a full semantic parser. It assigns
negative values to example markers, with fitted strengths for their forms.
A short text tail lets phrases cross token boundaries. Punctuation immediately
following certain example markers receives a continuation response.
Common liking and appearance patterns ('would like', 'looks like') are
excluded. The text tail and previous marker reset at document boundaries.
"""
import regex as re

READS = ()


def response(token, before):
    """Return a strength and a flag for generic punctuation continuation."""
    word = token.strip().lower()
    text = (before + token).lower()
    prior = before.lower().rstrip()
    previous = re.findall(r"[\w']+", prior[-50:])
    last = previous[-1] if previous else ''

    if re.search(r'\b(?:e\.g|z\.\s*b|p\.\s*ex)[.,]*$', text):
        return (-2.3, False) if word in ('.', '.,', ',') else (-3.1, False)
    if re.search(r'\beg[.,]*$', text) and (word in ('eg', '.', '.,')):
        return (-3.1, False)
    if re.search(r'\bex\.$', text):
        return (-6.0, False)
    if re.search(r'\bi\.e[.,]*$', text):
        return (-0.9, False)
    if word in ('example', 'examples', 'exemplary', 'exemplar'):
        if last == 'for':
            return (-2.4, True)
        if token.strip()[0].isupper():
            return (-2.5, True)
        if not token.startswith(' ') or last in ('=', '.', 'self'):
            return (-0.8, False)
        return (-1.5, True)
    if word == 'instance':
        return (-2.3, True) if last == 'for' else (-0.3, False)
    if word == 'is' and last == 'example':
        return (-1.1, False)
    if word == 'by' and last == 'exemplified':
        return (-3.5, False)
    if word == 'of' and re.search(r'\bin (?:the|this|that) case$', prior):
        return (-3.4, False)
    if word == 'of' and last in ('example', 'examples'):
        return (-0.5, False)
    if word == 'in' and last in ('as', 'illustrated', 'exemplified'):
        return (-1.2, False)
    if word == 'about' and last in ('how', 'what'):
        return (-2.3, False)
    if word == 'if' and (last in ('so', 'example', 'instance') or
                         re.search(r'\b(?:example|instance)[,:]$', prior)):
        return (-1.3, False)
