LATIN_SK = re.compile(
    r'(?:sk[aeiuy]?|(?:in|ow|ń|kow)sk[iy]?|isk[aeiy]|(?:or|an)sk)\Z'
)
CYR_SK = re.compile(
    r'ск(?:ий|ая|ое|ие|ого|ой|ому|ом|ую|их|им|ими|и|а|у|е|о)?\Z'
)
LATIN_K = re.compile(r'k(?:[aeiouy]|ie|ich|iego|ov)?\Z')
CYR_K = re.compile(r'к(?:[аиоеу]|ий|ой|ая|ое|ые|ого|ому|ом|ую|их|им|ими)?\Z')
