        return -4.1
    if a.startswith(' ') and CYR_SK.fullmatch(a[1:]):
        return -1.4
    if LATIN_SK.fullmatch(a):
        if s == 'Sk':
            return -0.5
        if a == 'sk':
            return -3.2 if b[-1:].isalpha() else -0.4
        if a.endswith(('ski', 'sky', 'insk')):
            return -7.3
        return -2.0
    if a in (' sk', ' ski', ' sky', ' skiing'):
        return -4.6 if a in (' ski', ' skiing') else -0.9
