    "between after before without about against per among out off".split()
)
CONJUNCTIONS = set(
    "and or but nor so if because although though while unless "
    "whether since until than".split()
)
POSSESSIVES = set("my your his her its our their".split())


def opening_value(text):
    word = text.strip()
    lower = word.lower()
    spaced = text.startswith(' ')
    if text == '<|im_start|>':
        return -6.55
    if not word:
        return -2.8
    if len(word) == 1 and word in '0123456789':
        if word == '0':
            return -2.87
        if word == '1':
            return -6.55
        return -6.8 if int(word) % 2 == 0 else -4.15
