        return -17.3 if spaced else (-19.7 if word.isupper() else -26.7)
    if lower == 'an':
        return -9.5 if spaced else -13.2
    if lower in POSSESSIVES:
        return -9.0 if spaced else -12.0
    if lower == 'one':
        return -13.4 if spaced else -17.5
    if lower in PREPOSITIONS:
        return -4.9 if spaced else -6.5
    if lower in CONJUNCTIONS:
        return -3.9 if spaced else -6.3
    if lower == 'the':
        return -6.7 if spaced else -7.5
    if len(word) == 1 and word.isalpha() and word.islower():
        return -9.8
    return -6.3 if spaced else -8.0


def step(carry, prefix, upstream):
    text = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    token = prefix.token_ids[-1]
    if carry is None or carry[0] != doc:
        first, initial = token, True
    else:
        _, first, initial = carry
        initial = initial and token == first
