"""Document-opening word detector for layers.1.mlp.down_proj:777.

What it does, in plain terms:
- It is silent almost everywhere. Its big responses come at the first token of each
  document: the first token of a row, or the token right after <|endoftext|>.
  There it goes negative, and how negative depends on what the word is:
    * determiners and quantifiers that open a noun phrase ("a", "an", "my", "your",
      "her", "one", "two", "some", "each", "every") are the most negative (about -13 to -17);
    * other words are moderately negative (about -6 to -8), single letters a bit more;
    * punctuation, code and digits are mild (about -3 to -5), spaces and newlines the mildest.
- The same value carries on while the document is only repeats of its first token
  (e.g. "··" "··" ...), since the model then has nothing but that token to attend to.
- The <|endoftext|> token itself gets a small positive value (about +1.5).
- Every other position gets 0.

Why: at a document's first token, attention can see only that token, so the response is
a function of which token it is. Opening determiners give the strongest response.
"""

READS = ()

EOS = "<|endoftext|>"
EOS_VALUE = 1.46

# determiners, possessives and small quantifiers that open a noun phrase
OPENERS = {
    "a", "an", "my", "your", "his", "her", "our", "their", "its",
    "one", "two", "three", "some", "any", "every", "each", "another", "no", "many", "several",
}


def start_value(s):
    """Activation at a document's first token, by what the token is."""
    w = s.strip()
    if s == "<|im_start|>":
        return -6.5
    if not w:
        return -3.0  # spaces and newlines
    if w.lower() in OPENERS:
        return -13.0 if s[:1] == " " else -17.0  # " a" vs "a"
    if w.isalpha():
        return -6.0 if s[:1] == " " else -8.0  # a word, with or without a leading space
    if w.isdigit():
        return -4.6
    return -4.3  # punctuation and code


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    new_doc = prefix.position == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]
    if new_doc:
        carry = (tok, True)  # (first token of this document, still only repeats of it)
        return carry, start_value(tok)
    if tok == EOS:
        return (carry[0], False), EOS_VALUE
    first, repeating = carry
    repeating = repeating and tok == first
    return (first, repeating), (start_value(tok) if repeating else 0.0)

