    'if': 0.7, 'for': 1.1, 'foreach': 1.15, 'while': 0.7,
    'switch': 1.15, 'catch': 1.15, 'try': 1.2, 'using': 1.3,
    'import': 0.7, 'function': 0.3, 'func': 0.12,
