    'grep', 'rg', 'find', 'ls', 'cat', 'head', 'tail', 'wc', 'sed',
    'awk', 'sort', 'cut', 'xargs', 'pytest', 'python', 'pip', 'git',
    'npm', 'mvn', 'cargo', 'go', 'curl', 'wget', 'chmod', 'rm', 'cp',
    'make', 'install', 'uninstall',
