import unicodedata

READS = ()


def response(previous, tail, token):
    if len(token) >= 64 and token == ' ' * len(token):
        return 1.35 if previous == token else 0.0
    s = token.lstrip(' \t')
    if s.startswith('\\t') and tail.endswith('\\t'):
        return 1.85
    if s == '\\' and tail.endswith(('\\n', '\\t')):
        return 0.6
    if s.startswith('\\n'):
        if tail.endswith('\\n'):
            return 0.9
        if tail.endswith(('\\r', '\\t')):
            return 0.4
    if s.startswith(('\\"', "\\'")):
        if tail.endswith(s[1]):
            return 5.1 if previous.strip() == s[:2] else 2.3
        if tail.endswith('\\'):
            return 1.3
        return 0.0
    for pair in ('[]', '{}', '()'):
        if previous.endswith(pair) and s.startswith(pair):
            return 4.5 if pair == '[]' else 1.5
    if not s or not previous:
        return 0.0
    ch = s[0]
    if ch != previous[-1] or ch == '\ufffd':
        if ch in '"”’' and previous[-1] in '"“‘':
            return 3.5
        return 0.0
    n = len(s) - len(s.lstrip(ch))
    m = len(previous) - len(previous.rstrip(ch))
    if ch == '\xa0':
        return min(3.0, 2.5 * n / m)
    if ch == '\r':
        return 0.27
    if unicodedata.category(ch)[0] not in 'PS':
        return 0.0
    if any(c.isalnum() for c in s):
        return 0.0
    if s != token:
        if ch in '|>':
            return 2.4
        if ch in '*&':
            return 1.9
        if ch in "`'\"":
            return 0.8 if token == previous else 0.3
        if ch == '_':
            return -0.15
        return 0.5 if ch.isascii() else 1.1
    # Backtick fences peak on the second chunk, then weaken.
    if ch == '`':
        if n == 1 and '\n' in s:
            if m > 2:
                return 2.6
            return 0.75 if s.count('\n') > 1 else 1.0
        if n == 1:
            return 6.2 if m == 1 else 3.3
        run = len(tail) - len(tail.rstrip('`'))
        if n == 2:
            return 6.0 if run == 2 else 4.0
        return 2.5
    if ch in "'\"":
        if '\n' in s:
            return 1.8
        return 4.2 if ch == "'" else 3.0
    if ch == '^':
        if m == 1:
            return 7.7
        return 4.4 if m == 2 else 3.2 * min(1.0, n / 4)
    if ch in '!?':
        return 4.8 if m == 1 else 2.8
    if ch == '*':
        return 6.0 if m <= 2 else 2.0
    if ch in '+~':
        if m == 1:
            return 3.7 if n <= 2 else 4.8
        return 2.2
    if ch in '<>|':
        return 3.4
    if ch == '$':
        return 4.7 if n > 1 else 2.8
