    if ch in '-_=./#':
        if ch in '/#':
            return 1.0 if '\n' in s else 2.0 * min(1.5, n / m)
        scale = {'-': 1.6, '_': 2.5, '=': 0.8, '.': 3.0}[ch]
        value = scale * min(1.5, n / m)
        return value * (0.6 if '\n' in s else 1.0)
