    if category in ('Pi', 'Pf'):
        return 2.0 if '\n' in s else 4.5
    if 'STAR' in name or 'ARROW' in name:
        return 4.0
    if category in ('So', 'Sm') or 'PILCROW' in name:
        return 0.0
    return 3.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
