"""Doubled-delimiter detector for layers.1.mlp.down_proj:785.

The component fires when a punctuation token continues a run of the same
delimiter character started by the token just before it:

- a second escaped quote in a doubled quote (\\"\\" in code strings), or a quote
  that repeats the quote before it;
- a second backtick, most strongly a backtick right after "(" (the start of an
  inline code span in code comments);
- the caret or plus marks under a compiler error message (^^^^, ++++);
- a repeated '<' or '>';
- a backslash-quote right after a backslash (weak);
- runs of the middle dot used as leader dots (·····), which fire strongly;
- other repeated symbol tokens (weak).

Strengths are typical activation sizes for each case, fitted on training rows.
Every other position predicts 0. It needs only the previous token.
"""
READS = ()

PUNCT = set("!\"#$%&'()*+,-./:;<=>?@[\\]^_`{|}~")


def _is_delim(s):
    return bool(s) and set(s) <= PUNCT


def _is_symbol(s):
    s = s.strip()
    return bool(s) and not any(c.isalnum() for c in s)


def step(carry, prefix, upstream):
    cur = prefix.token_strings[-1]
    prev = prefix.token_strings[-2] if len(prefix) > 1 else ""
    if cur == "··" and prev == "··":
        return carry, 5.2
    if not (_is_delim(cur) and _is_delim(prev)):
        if _is_symbol(cur) and cur == prev:
            return carry, 0.5
        return carry, 0.0
    if '\\"' in cur and prev.endswith("\\"):
        return carry, 0.9
    shared = (set(cur) & set(prev)) - set("\\")
    if not shared:
        return carry, 0.0
    if set(cur) <= set("^+"):
        return carry, 2.6
    if "`" in shared:
        return carry, 6.5 if "(" in prev else 4.4
    if '"' in shared and (cur.startswith('"') or cur.startswith('\\"')):
        return carry, 3.1
    if shared & set("<>"):
        return carry, 1.8
    return carry, 0.5

