"""A local spelling response centered on wi/we fragments.

The negative side favors isolated wide/wise roots and their split spellings;
wig/weg-like continuations have the opposite sign. Whole, familiar words
such as 'with', 'will' and 'window' are not treated as these fragments.
A small offset handles the first token; initial runs of middle dots,
carets and escape sequences have separate positive responses. State is
only the preceding token, 48 trailing characters, and the initial-run flag;
it resets at each document boundary. The rounded amplitudes approximate
training measurements; lexical and longer-context variation is left out.
"""
import re

READS = ()


def activation(token, previous, tail, first):
    s = token.strip()
    low = s.lower()
    prev = previous.lower()
    if first and low and set(low) == {'·'} and len(low) >= 2:
        return 5.7
    if first and low and set(low) == {'^'} and len(low) >= 4:
        return 5.8
    if first and s in (r'\n', r'\t', r'\"'):
        return {r'\n': 4.6, r'\t': 7.8, r'\"': 4.1}[s]

    # A suffix kept in a separate token is stronger than a fused compound.
    if low in ('wide', 'wider', 'widest', 'widely', 'widen',
               'widened', 'widening', 'wid'):
