                r'\b(der|dem|und|sei|uff|von|gestern)\b', tail.lower()):
            return -6.5
        elif low == 'wide' and re.search(
                r'\b(world|county|country|nation|city|genome)$', tail.lower()):
            return -9.0
        elif low in ('widely', 'widest', 'widened'):
            value = -2.9
        if s[:1].isupper() and low != 'wid':
            value *= 1.8
        return value
    if low == '-wide':
        if prev.endswith('genome'):
            return -11.0
        if re.search(r'(foot|feet|inch|metre|meter|ultra)$', prev):
            return -4.0
        return -8.0
    if low.endswith('wide'):
        return -1.5
    if low.endswith('wise'):
        if re.search(r'(clock|other|like|un)wise$', tail.lower() + low):
            return 0.0
        value = -2.5 if token[:1].isspace() else -4.8
        if re.search(r'(piece|point|element|step)$', tail.lower()):
            value = -6.0
        if tail.lower().endswith('component'):
            value = -9.0
        if low == 'pairwise':
            value = -4.2
        if s[:1].isupper():
            value = -5.2
        return value
    if low in ('wieder', 'weit', 'weiter', 'weise', 'weis'):
        return {'wieder': -4.1, 'weit': -3.6, 'weiter': -1.5,
                     'weise': -1.6, 'weis': -1.3}[low]
    if low in ('wig', 'weg', 'wegen'):
        return {'wig': 4.8, 'weg': 0.9, 'wegen': 2.1}[low]
    if low == 'wives' and not token[:1].isspace():
        return -3.0
    if low in ('wi', 'wie', 'wiel', 'wis', 'wit', 'wife', 'wive', 'wives'):
        val = {'wi': -2.8, 'wie': -0.7, 'wiel': -0.8, 'wis': -1.7,
               'wit': -1.0, 'wife': -0.4, 'wive': -1.0, 'wives': -0.3}[low]
        if low == 'wi' and not token[:1].isspace():
            val = -3.3
        return val
    if low in ('vig', 'vik', 'wick'):
        if low == 'vig' and token[:1].isspace():
            return 0.0
        return {'vig': 2.9, 'vik': 0.8, 'wick': 0.7}[low]
    if low == 'we' and token == 'we':
        return -1.0
    if low == 'w' and token == 'w' and tail[-1:].isalpha():
        return -0.3

    # Joined spellings at a token boundary, not a previous word.
    if token[:1].isspace():
        return 0.0
