    if previous.endswith('ว') and low == 'ิ':
        return -4.2
    if prev.endswith('v') and low.startswith('ě'):
        return -1.0
    if re.search(r'w[iey]{0,4}$', prev):
        scale = 0.55 if re.search(r'[aou]w$', prev) else 1.0
