    else:
        _, previous, tail, initial = carry
        if token != initial:
            initial = None
    value = activation(token, previous, tail, initial is not None)
    if reset and value == 0.0:
        value = 0.17
    return (doc, token, (tail + token)[-48:], initial), float(value)

