"""Approximate a negative response to the beginning of a document.

The response persists when the opening token is repeated.  Its average size
varies with token type.  Opening digits have their own small calibration;
Opening '12' (also its next repeated '2') and 'Hydro' get larger responses.
Later tokens get small positive responses for negation, acknowledgements,
identity and precision words, and exception markers; otherwise zero.
Most weaker, token-specific variation is deliberately left unexplained.
"""
READS = ()

# Calibration for the ten ordinary decimal digits, only at document onset.
DIGIT_ONSET = (-0.175, -0.629, -0.318, -0.236, -0.368,
               -0.442, -0.554, -0.587, -0.434, -0.499)


def onset(token):
    if not token:
        return 0.0
    if len(token) == 1 and token in '0123456789':
        return DIGIT_ONSET[int(token)]
    if token == r'\t':
        return -1.258
    if '\t' in token:
        return -0.82
    if token.startswith('<|'):
        return -0.382
    if token[0].isspace():
        return -0.33
    if token.isascii() and token.isalpha():
        return -0.54
    if all(not c.isalnum() for c in token):
        return -0.29
    return -0.43


NEGATION = frozenset('not never nothing none neither cannot'.split())
ACKNOWLEDGEMENTS = frozenset('yes ok okay'.split())
IDENTITY = frozenset(
    'same equal equals identical equivalent exactly equality'.split())
EXCEPTIONS = frozenset(('except', 'unless'))


def later(token):
    word = token.strip().lower()
    if word in NEGATION:
        return 0.06
    if word in ACKNOWLEDGEMENTS:
        return 0.10
    if word in IDENTITY:
        return 0.05
    if word in EXCEPTIONS:
        return 0.08
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        position, first, repeated, beginning = (
            0, prefix.token_ids[-1], True, '')
    else:
        _, position, first, repeated, beginning = carry
        repeated = repeated and prefix.token_ids[-1] == first
    if position < 3:
        beginning += token
    value = onset(token) if repeated else later(token)
    if position == 1 and beginning == '12':
        value = -2.62
    elif position == 2 and beginning == '122':
        value = -1.18
    elif position == 1 and beginning == 'Hydro':
        value = -1.70
    return (doc, position + 1, first, repeated, beginning), value

"""A sparse mixture of document-opening and code-syntax responses.

Opening tokens are grouped by punctuation, whitespace, case and common
function words. Within a document, positive cues include function declarations,
Python from-import statements and command words. There are also small rules
for title endings, double backslashes and repeated middle-dot filler.
These are coarse training-derived estimates; most other positions get zero.
State tracks the previous token and a bounded line, reset at document changes.
"""
import re
import unicodedata

READS = ()
ARTICLES = {'a', 'an', 'the'}
COMMANDS = {'test', 'run', 'install', 'build', 'start'}
FUNCTION_WORDS = {
    'a', 'an', 'the', 'to', 'in', 'on', 'of', 'for', 'and', 'with',
    'is', 'as', 'at', 'by', 'it', 'or', 'be',
}


def opening(s):
    w = s.strip()
    if w in ('def', 'fn', 'func', 'function', 'package'):
        return 1.3
    if w in ('\"\"\"', "'''"):
        return -0.65
    if w and set(w) <= set(',.;:!?。；，：！？'):
        return 1.36
    if w in FUNCTION_WORDS:
        if w in ARTICLES:
            return 1.3
        if w in ('to', 'in', 'with', 'as', 'and', 'or'):
            return 1.2
        return 0.17
    if s and set(s) == {' '}:
        return 1.47 if len(s) <= 2 else 2.42
    if any(c in w for c in '\"“”'):
        return 2.63 if len(w) == 1 else 1.59
    if s.startswith('<|'):
        return -0.25
    if w and not w[0].isalnum():
        punctuation = all(unicodedata.category(c)[0] in 'PS' for c in w)
        if not punctuation:
            return 0.78
        return 1.32 if any(c in w for c in "'‘’") else 0.24
    if w.lower() in FUNCTION_WORDS:
        return 0.25
    return -0.16 if w.istitle() else 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    if first:
        previous, line = '', ''
    else:
        _, previous, line = carry
    s = prefix.token_strings[-1]
    w = s.strip()
    if (w and set(w) == {'·'} and len(w) >= 2
            and (first or previous == s)):
