    elif (w == 'import' and s.startswith(' ')
          and re.search(r'^\s*(?:\d+[:\s]+)?from\s+[\w.]+\s*$', line)):
        value = 1.5
    elif '\n' in s and line.startswith('Title:'):
        value = -0.63
    elif w == 'def' and previous.strip() not in ('_', '.'):
        value = 0.8 if not line.strip() else 0.3
    elif w == 'fn':
        value = 0.97 if s.startswith(' ') else 0.35
    elif w in ('func', 'function'):
        value = 0.14 if s.startswith(' ') else 0.41
    elif (previous.strip() in ('-', '--') and s == w
          and w.isalpha() and len(w) == 1):
        value = 0.15
    elif w in COMMANDS and re.search(r'\b(npm|pnpm|yarn|cargo|go)\s*$', line):
        value = 0.75
    elif w == '\\\\':
        value = -0.35 if s.startswith(' ') else 0.3
    else:
        value = 0.0
    # Source code may be embedded in a quoted string with escaped newlines.
    line = (line + s).replace('\\n', '\n').split('\n')[-1][-200:]
    return (doc, s, line), value

