1. The very first token of a row (position 0, which the model reads with no context).
   If that token is punctuation, a symbol, whitespace, or a common function word
   ("a", "the", "to", "and", "in", ...), it fires strongly. Content words, names and
   capitalised openers stay near zero. Document breaks in the middle of a row do not
   fire it.

2. Source-code declaration and import syntax, mid-text:
   - "import" inside a `from X import Y` line fires (line-start `import x` does not).
   - "::" inside a Rust `use` line fires.
   - "fn" after "pub" (Rust) fires strongly; other "fn", and "def", "func",
     "function", "init", fire weakly.

Everything else predicts 0. The weights are rough averages measured on training rows.

Limits: this explains the spikes, about 17% of the variance. Most of the rest is small,
diffuse activity (rms ~0.05) with no simple token or context rule, and it is what the
model actually uses for next-token predictions, so switching the component off and
using this program change the model's output by similar amounts.
"""

# Common function words that can open a text fragment (with their leading space).
FUNCTION_WORDS = {
    " a", " an", " the", " to", " and", " or", " of", " in", " on", " at", " by",
    " for", " with", " from", " as", " is", " that", " it", " be",
}
# Keywords that open a function or module definition.
DECLARATION_WORDS = {"def", "fn", "func", "function", "init"}

READS = ()


def step(carry, prefix, upstream):
    t = prefix.position
    token = prefix.token_strings[-1]
    word = token.strip()

    # Per-line flags: has "from" / "use" / "pub" appeared on the current line?
    # Reset at the row start, at a document change, and after each newline.
    if t == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]:
        line = (False, False, False)
    else:
        line = carry
    seen_from, seen_use, seen_pub = line

    if t == 0:
        # First token of the row: punctuation/whitespace or a function word fires.
        if word == "" or not word[0].isalnum():
            value = 0.8
        elif token in FUNCTION_WORDS:
            value = 0.9
        else:
            value = 0.0
    elif token in (" import", "import") and seen_from:
        value = 1.2
    elif token in ("::", "::{") and seen_use:
        value = 0.9
    elif word == "fn":
        value = 1.0 if seen_pub else 0.4
    elif word in DECLARATION_WORDS:
        value = 0.4
    else:
        value = 0.0

    if "\n" in token:
        line = (False, False, False)
    else:
        if token in (" from", "from"):
            seen_from = True
        if token in (" use", "use"):
            seen_use = True
        if token in (" pub", "pub", " pub(crate)"):
            seen_pub = True
        line = (seen_from, seen_use, seen_pub)
    return line, value

programs.sol:
"""A printable school-materials signal, with a few formatting responses.

Recognize worksheets and printables, including split spellings. Distinguish
school grades (an ordinal before 'grade') from other senses. Coloring pages,
lesson plans and mathematical-resource offers supply related cues. Separate
rules cover email redaction, repeated dots and initial title punctuation.
This is a lexical approximation, not a general education-topic classifier.
"""
import re
import inflect

READS = ()
_english = inflect.engine()
ORDINALS = {
    _english.number_to_words(_english.ordinal(n)) for n in range(1, 13)
}
MATH_RESOURCES = re.compile(
    r'\b(math|algebra|worksheet|worksheets|calculus|dummies)\b'
)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        tail = ''
    else:
        tail = carry[1]
    text = prefix.token_strings[-1]
    word = text.strip()
    lower = word.lower()
    before = tail.lower()
    previous = re.search(r'(\w+)\s*$', before)
    previous = previous.group(1) if previous else ''
    joined = (tail + text)[-120:]
    value = 0.0

    if lower == 'worksheets' or (
        lower == 'heets' and before.endswith('works')
    ):
        value = 10.0 if word[:1].isupper() else 7.8
        if previous == 'printable':
            value = 10.5
        elif re.search(r'\b(excel|workbook)\b', before):
            value = 1.4
    elif lower in {'printable', 'printables'}:
        value = 8.8 if lower.endswith('s') else 5.3
    elif lower in {'able', 'ables'} and before.endswith('print'):
        value = 11.3 if lower == 'able' else 8.8
    elif lower == 'worksheet':
        value = 1.05 if word[:1].isupper() else 0.67
    elif lower == 'sheets' and previous == 'work':
        value = 4.0
    elif lower == 'pages':
        if previous in {'coloring', 'colouring'}:
            value = 8.0
        elif 'print out these' in before[-30:]:
            value = 5.0
        elif previous == 'github':
            value = 2.9
        elif before.endswith('number of'):
            value = 2.4
        elif previous == 'printed':
            value = 1.5
        else:
            value = 0.16
            if word[:1].isupper():
                value = 0.55 if previous.isdigit() else 1.35
    elif lower == 'page' and previous == 'this':
        value = 0.95 if tail.endswith('This') else 0.28
    elif lower == 'page' and before.endswith('printer friendly'):
        value = 1.4
    elif lower == 'grade':
        if previous in ORDINALS:
            value = 2.5
        elif re.fullmatch(r'\d+(st|nd|rd|th)', previous):
            value = 1.4
        elif previous in {'math', 'level'}:
            value = 1.3
    elif lower == 'plan' and previous == 'lesson':
        value = 1.1
    elif lower == 'free':
        value = 0.28 if word[:1].isupper() else 0.16
        if MATH_RESOURCES.search(before):
            value = 1.1
        elif previous == 'online':
            value = 0.58
    elif lower == 'protected' and re.search(r'\[email\s*$', before):
        value = 0.65 if text.startswith(' ') else 1.3
    elif word == '··' and (not tail or tail.endswith('··')):
        value = -1.55
    elif word == ':' and tail == 'Title':
        value = -2.75

    return (doc, joined), value

"""Recognize single-space tokens that continue horizontal blank runs.

Ordinary word separators are quiet. A single ASCII space continuing a
space run gets a large positive value, adjusted coarsely for the preceding
chunk's width. Repeated tabs are weaker. Nonbreaking spaces have a weak
response except in indentation following backtick code markup.
Longer space tokens are quiet, apart from document-initial ASCII blanks.
"""
READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    same_document = (len(prefix.document_ids) > 1 and
                     prefix.document_ids[-1] == prefix.document_ids[-2])
    previous = prefix.token_strings[-2] if same_document else ''
    code_spacing = bool(carry) if same_document else False
    value = 0.0

    if token == ' ' and previous.endswith(' '):
        width = len(previous) - len(previous.rstrip(' '))
        if width == 1:
            value = 1.14
        elif width < 6:
            value = 1.42
        else:
            value = 1.1
    elif token == '\t' and previous.endswith(('\t', ' ')):
        value = 0.26 if len(previous) == 1 else 0.44
    elif token == '\xa0':
        if previous.endswith('\xa0'):
            value = 1.45 if code_spacing else 0.35
        elif code_spacing:
            value = 0.5
    elif not same_document and token and not token.strip(' '):
        value = 0.5

    # Remember whether the current blank run follows a code delimiter.
    if '\n' in token:
        code_spacing = False
    elif token and not token.isspace():
        code_spacing = '`' in token
    return code_spacing, value

"""Recognize the base/foundation character 基 and a few common compounds.

The strongest responses are to 基 itself, funds (基金), and 'based on'
(基于). Basics and foundations are weaker; names of bases/stations are not
included. There is also a small response on English 'on' after 'based'.
The UTF-8 prefix shared by 基 and other Han characters, and split
spellings of 基于/基金, are recognized using a short byte/text tail, reset between documents. The
Japanese/Korean syllable ki/gi gives a modest response, with a stronger one
on completing Korean 기금 (fund) or 기초 (basis). Otherwise the first token
of a document has a negative default based on whitespace, digits and case.
"""
import re

READS = ()


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    fresh = carry is None or carry[0] != document
    tail = '' if fresh else carry[1]
    byte_tail = b'' if fresh else carry[2]
    token = prefix.token_strings[-1]
    raw = prefix.token_bytes[-1]
    word = token.strip()
    value = 0.0
    if word == '基':
        value = 5.4
    elif word == '基金':
        value = 4.2
    elif word == '基于':
        value = 4.4
    elif word in ('基层', '基准'):  # grassroots, benchmark
        value = 3.9
    elif word == '基本':
        value = 2.35
    elif '基本' in word and not word.endswith(('面', 'に')):
        value = 1.3
    elif '基础' in word:
        value = 1.4 if not word.endswith('上') else 0.9
    elif word == '基礎':
        value = 0.65
    elif word in ('根基', '基石', '基建'):  # roots, cornerstone, infrastructure
        value = 1.5
    elif word.lower() == 'on' and re.search(r'\bbased\s*$', tail, re.I):
        value = 0.9 if re.search(r'\bBased\s*$', tail) else 0.4

    joined = byte_tail + raw
    if joined.endswith(b'\xe5\x9f'):
        value = 6.2
    elif raw == b'\xba' and byte_tail.endswith(b'\xe5\x9f'):
        value = 7.8
    elif byte_tail.endswith('基'.encode()) and word in ('于', '於', '金'):
        value = 7.0 if word != '金' else 8.5
    elif byte_tail.endswith('基'.encode()) and word in ('準', '准', '点'):
        value = 1.9
    if word in ('기', 'キ'):
        value = 0.5
    elif tail.endswith('기') and word in ('금', '초'):
        value = 7.5 if word == '금' else 4.8
    if fresh and value == 0.0:
        if not word:
            value = -0.05 if token.startswith(' ') else -0.65
        elif word.isdecimal():
            value = -0.14
        elif token.startswith(' '):
            value = -0.25
        elif word.isascii() and word.isalpha():
            value = -0.65 if word.islower() else -0.5
        else:
            value = -0.35
    return (document, (tail + token)[-40:], joined[-4:]), value

"""Opening quotes of object fields, with weaker responses to list items.

A quote following a short key/value pair is strongly negative. A quote
following the colon itself (the beginning of a value) is not. Indented
fields and quoted lists are weaker. Most other tokens are predicted zero.
A separate rule covers a document-initial Title: metadata header.
Only a bounded recent context is kept, reset at document boundaries.
"""
import math
import re

READS = ()
FIELD_SEPARATOR = re.compile(r'''["']\s*(?::|=>)''')
TRAILING_SPACE = re.compile(r'(?:\s|\\n)+$')


def quote_value(token, recent):
    if token in (' {"', " {'"):
        return -0.15 if token.endswith('"') else -0.21
    compact = re.fullmatch(r'''(?:\\?["'])?,\\?(["'])''', token)
    quote = compact[1] if compact else token.strip().lstrip('\\')
    if quote not in ('"', "'"):
        return 0.0
    spaced = token.startswith(' ')
    if not recent:
        return (-0.28 if quote == '"' else -0.20) if spaced else 0.0
    text = ''.join(recent) + (',' if compact else '')
    bare = not spaced and '\\' not in token
    end = TRAILING_SPACE.sub('', text)
    if end.endswith((':', '=>')):
        return 0.02 if spaced else 0.0
    if end.endswith('{'):
        strength = 1.15 if quote == '"' else 0.70
        return -strength * (0.65 if bare else 1)
    comma = end.endswith(',')
    indent = recent[-1].isspace()
    if not spaced and not comma and not text.endswith(('\n', ' ', '\t')):
        return 0.0
    if not (comma or indent):
        return 0.01 if spaced else 0.0
    fields = list(FIELD_SEPARATOR.finditer(text))
    if fields:
        tail = text[fields[-1].end():]
        # Quotes inside an array-valued field are list items instead.
        if tail.lstrip().startswith('[') and ']' not in tail:
            return -0.08 if compact else -0.22
        distance, length = 0, 0
        for part in reversed(recent):
            distance += 1
            length += len(part)
            if length > len(tail):
                break
        strength = 1.45 if quote == '"' else 1.05
        if '\\' in token:
            strength *= 0.8
        elif bare:
            strength *= 0.65
        if indent and not comma:
            strength *= 1 / (1 + len(recent[-1].expandtabs(4)) / 8)
        if any(c in ''.join(recent[-3:]) for c in '}]'):
            strength *= 0.6
        return -strength * math.exp(-max(0, distance - 6) / 45)
    # Without a field separator, distinguish containers from function calls.
    container = max(text.rfind('{'), text.rfind('['))
    call = text.rfind('(')
    if container > call:
        return -0.4 if text[container] == '{' else -0.22
    if call >= 0:
        return 0.04
    return 0.02


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    recent = [] if carry is None or carry[0] != doc else carry[1]
    token = prefix.token_strings[-1]
    value = quote_value(token, recent)
    if not recent and token == "Title":
        value = 0.67
    elif recent == ["Title"] and token == ":":
        value = -2.86
    recent = (recent + [token])[-64:]
    return (doc, recent), value

programs.haiku:
"""Quoted keys of JSON-like objects: a negative push on the opening quote of a key.

The component writes a push against the key-opening quote of an object: the quote that starts
a key in a `{...}` object (JSON, a Python or JS dict literal) after an earlier `key: value,`
entry, or at the start of a new line in a multi-line object. PHP-style `[ 'key' => value ]`
arrays count too once a pair has appeared. Inside a model tool call (`<tool_call>` ...
`</tool_call>`) the push is about -1.4; elsewhere about -0.7. Quotes that open values, prose
quotes, first keys written inline after `{`, and plain list items stay near zero.
"""

READS = ()

QUOTES = "\"'"
TOOL_OPEN, TOOL_CLOSE = "<tool_call>", "</tool_call>"
TOOL_VALUE, OTHER_VALUE = -1.4, -0.7


def _fresh(document):
    return {"doc": document, "stack": [], "in_str": False, "quote": None, "esc": False,
            "last": "", "nl": False, "bs": False, "recent": "", "tool": False}


def _run(st, text):
    """Advance the parser over one token's text; True if it opens a key."""
    hit = False
    for c in text:
        if st["in_str"]:
            if st["esc"]:
                st["esc"] = False
            elif c == "\\":
                st["esc"] = True
            elif c == st["quote"]:
                st["in_str"], st["last"], st["nl"] = False, c, False
            elif c == "\n":
                st["in_str"], st["nl"] = False, True
            continue
        if st["bs"] and c == "n":  # a literal backslash-n, as in JSON-escaped code
            st["bs"], st["nl"] = False, True
            continue
        st["bs"] = c == "\\"
        if c in QUOTES:
            top = st["stack"][-1] if st["stack"] else ["", False]
            last, nl = st["last"], st["nl"]
            in_object = top[0] == "{" and (last == "," or (nl and last not in ":+=("))
            in_list = top[0] == "[" and top[1] and last == ","
            if in_object or in_list:
                hit = True
            st["in_str"], st["quote"], st["last"], st["nl"] = True, c, c, False
        elif c in "{[(":
            st["stack"].append([c, False])
            st["last"], st["nl"] = c, False
        elif c in "}])":
            if st["stack"]:
                st["stack"].pop()
            st["last"], st["nl"] = c, False
        elif c in ":>" and (c == ":" or st["last"] == "="):
            if st["stack"]:
                st["stack"][-1][1] = True  # a key: value pair has appeared in this container
            st["last"], st["nl"] = c, False
        elif c == "\n":
            st["nl"] = True
        elif not c.isspace():
            st["last"], st["nl"] = c, False
    return hit


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    if carry is None or carry["doc"] != document:
        carry = _fresh(document)
    text = prefix.token_strings[-1]
    hit = _run(carry, text)
    carry["recent"] = (carry["recent"] + text)[-40:]
    if TOOL_OPEN in carry["recent"]:
        carry["tool"] = True
    if TOOL_CLOSE in carry["recent"]:
        carry["tool"] = False
    value = 0.0
    if hit:
        value = TOOL_VALUE if carry["tool"] else OTHER_VALUE
    return carry, value

programs.sol:
"""An i/y spelling contrast across pieces of a word.

A continuation after an i-bearing piece is usually positive if it has no i,
but negative if it begins with another i. Short word prefixes and short
continuations strengthen this contrast. A previous y gives a weaker version.
Earlier i's in the same word also mildly suppress a new initial i. Other
positions are near zero. This is a spelling rule, not a word-identity table.
"""
import re
from anyascii import anyascii

READS = ()
TRAILING_LETTERS = re.compile(r'[^\W\d_]+$')


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, word = '', ''
    else:
        _, previous, word = carry
    token = prefix.token_strings[-1]
    s = token.strip().lower()
    p = previous.lower()
    value = -0.00019
    continuation = (token and token[0].isalpha() and previous
                    and previous[-1].isalpha())
    if continuation:
        if 'i' in p:
            if 'i' not in s:
                if len(word) <= 4:
                    if len(s) <= 3:
                        value = 0.674 if any(c in s for c in 'aeiou') else 0.475
                    else:
                        value = 0.304
                elif len(previous.strip()) <= 5:
                    value = 0.337 if len(s) <= 3 else 0.163
                else:
                    value = 0.078
            elif s.startswith('i'):
                value = -0.464 if len(previous.strip()) <= 3 else -0.154
            else:
                value = 0.006
        elif 'y' in p:
            if 'i' in s:
                value = -0.045
            else:
                value = 0.357 if len(word) <= 3 else 0.156
        elif s.startswith('i'):
            value = -0.102 if 'i' in anyascii(word).lower() else 0.076
        else:
            value = 0.010
    if token.isalpha():
        word = (word if previous and previous[-1].isalpha() else '') + token
    else:
        match = TRAILING_LETTERS.search(token)
        word = match.group() if match else ''
    return (doc, token, word), value

programs.haiku:
"""Layer-1 MLP neuron 798 (down_proj), as a word-spelling rule.

What it responds to: pieces of a word that is split across tokens (the
continuation pieces, not the first piece and not whole words). Within those,
it is driven by the letter "i" in the word so far:
  * the piece just before has an "i" and the new piece has none: strongly positive;
  * an "i" appeared earlier in the word, but not in the piece just before: mildly positive;
  * the new piece also contains an "i" (the word already had one): negative;
  * any other continuation piece: near zero.
Everything else is zero. The rule explains about a tenth of the variance; the
exact size within each case depends on the particular word, which is not modelled.
"""

READS = ()

PREV_I = 0.40        # previous piece has "i", new piece has none
EARLIER_I = 0.09     # an earlier piece of the word has "i", new piece has none
I_AGAIN = -0.13      # new piece has "i" and the word already had one
OTHER = 0.02         # any other continuation piece


def _is_letters(s):
    return s != "" and s[0] != " " and s.isalpha()


def _is_word_start(s):
    return len(s) > 1 and s[0] == " " and s[1:].isalpha()


def step(carry, prefix, upstream):
    strings = prefix.token_strings
    docs = prefix.document_ids
    token = strings[-1]
    if not _is_letters(token):
        return None, 0.0
    # Walk back over the earlier pieces of this word, within the same document.
    earlier_i = 0
    has_earlier = False
    prev_i = False
    j = len(strings) - 2
    while j >= 0 and docs[j] == docs[-1]:
        s = strings[j]
        if _is_letters(s) or _is_word_start(s):
            if has_earlier is False:
                prev_i = "i" in s
            earlier_i += s.count("i")
            has_earlier = True
            if _is_word_start(s):
                break
            j -= 1
        else:
            break
    if not has_earlier:
        return None, 0.0
    new_i = "i" in token
    if new_i and earlier_i >= 1:
        value = I_AGAIN
    elif not new_i and prev_i:
        value = PREV_I
    elif not new_i and earlier_i >= 1:
        value = EARLIER_I
    else:
        value = OTHER
    return None, value

programs.sol:
"""Approximate a negative enumeration / specification-opening signal.

Look for inclusion words, example phrases, plural copulas, and colons.
Nearby collection headings, quantifiers, and a plural preceding word
strengthen the response. Carry the opening through a first list marker.
A separate punctuation rule recognizes repeated middle-dot leaders.
This is a lexical/grammatical approximation, not a full syntactic parser.
"""
import re

READS = ()
COLLECTIONS = frozenset('''type kind category example option method way reason
component element feature item term part section aspect form group step choice
technique ingredient symptom parameter objective recipe principle benefit
requirement mode variable root answer factor candidate set list variety range
number series stage segment channel program species network'''.split())
QUANTIFIERS = frozenset('''several various many numerous some following these
those other multiple different both main key common important major'''.split())
CARDINALS = frozenset('two three four five six seven eight nine ten'.split())
PERSONAL = frozenset('i you we he she it there who that what'.split())
MODALS = frozenset('to may can could should will would shall must not'.split())
FUNCTIONS = PERSONAL | MODALS | frozenset('''a an the and or of in on at for
with as be is'''.split())
EXAMPLE_TRANSLATIONS = frozenset('例如 比如 包括 如 其中 例えば notamment nämlich'.split())
COPULA_TRANSLATIONS = frozenset('são sont sind sono son である'.split())
INTRODUCERS = frozenset('''include includes including included are were follows
following namely either'''.split())


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', '', 0.0, False)
    _, text, line, pending, number = carry
    token = prefix.token_strings[-1]
    s = token.strip()
    word = s.lower()
    words = re.findall(r'[^\W\d_]+', text.lower())
    previous = words[-1] if words else ''
    recent = words[-12:]
    nouns = min(3, sum(w.rstrip('s') in COLLECTIONS or w == 'categories'
                       for w in recent))
    quantities = min(3, sum(w in QUANTIFIERS for w in recent))
    cardinals = min(2, sum(w in CARDINALS for w in recent)
                    + len(re.findall(r'\b[2-9]\b', text[-100:])))
    boundary = not text or not text[-1:].isalpha() or token[:1].isspace()
    value, contextual, colon = -0.003, False, False

    if boundary:
        contextual = True
        if word == 'include':
            value = -0.67 if previous in MODALS else -2.06
        elif word in ('including', 'included', 'comprising'):
            value = -0.63
        elif word in ('includes', 'comprises'):
            value = -0.40
        elif word in ('namely', 'notably', 'specifically'):
            value = -1.41
        elif word in ('are', 'were'):
            value = -0.31
        elif word in COPULA_TRANSLATIONS:
            value = -0.45
        elif word == 'such':
            value = -0.24
        elif word == 'as' and previous == 'such':
            value = -0.82
        elif word == 'like':
            value = -0.15
        elif word in ('first', 'firstly', 'secondly', 'thirdly') or (
                word == 'one' and re.search(r'[,.:]\s*$', text)):
            value = -0.26
        else:
            contextual = False
            if word in ('example', 'instance') and previous == 'for':
                value = -1.31
            elif word == 'either':
                value = -0.97
            elif word == 'following' and previous in ('the', 'as'):
                value = -0.36
            elif s == 'There':
                value = -0.27
    if s in EXAMPLE_TRANSLATIONS:
        value, contextual = -1.23, True
    # Include-family words can be split over several tokens.
    if ((boundary and word.startswith('incl')) or
            (not boundary and re.search(r'\bincl[^\s]*$', text.lower()))):
        if word not in ('include', 'includes', 'including', 'included'):
            value, contextual = -0.63, True
    end = (text + token)[-220:]
    if re.search(r'\b(?:i\.e|e\.g)\.?[,]?$', end, re.I):
        value, contextual = -0.48, False

    if re.fullmatch(r'\s*[:：][\s\\n]*', token):
        value, contextual, colon = -0.18, True, True
    elif s in ('{"', '{\\"', '{', '["'):
        value, contextual = (-0.54 if '"' in s else -0.07), False
    elif s in ('(', '(**'):
        value, contextual = -0.03, False
    elif not line.strip() and (s in ('-', '*', '•', '○', '✓') or s.isdigit()):
        value, contextual, number = -0.08 - 0.34 * pending, False, s.isdigit()
    elif number and s in ('.', ')', '．'):
        value, contextual, number = -0.08 - 0.34 * pending, False, False
    elif not s and pending:
        value, contextual = -0.26, False
    if len(s) >= 2 and set(s) == {'·'}:
        value, contextual = 0.62, False

    if contextual:
        value -= 0.08 * nouns + 0.33 * quantities
        if previous.endswith('s') and previous not in FUNCTIONS:
            value -= 0.35
        if previous in PERSONAL:
            value += 0.10
        if previous in FUNCTIONS:
            value += 0.17
        if re.search(r'[=;{}]|["\']\s*$', line):
            value += 0.11
        if '\n' in token:
            value -= 0.18
        if colon and previous in INTRODUCERS:
            value -= 1.65

    marker = (not line.strip() and
              (s in ('-', '*', '•', '○', '✓') or s.isdigit()))
    if colon:
        pending = 1.0 + nouns + min(cardinals + quantities, 3)
    elif s and not marker and not (carry[4] and s in ('.', ')', '．')):
        pending, number = 0.0, False
    line = (line + token).replace('\\n', '\n').rsplit('\n', 1)[-1][-180:]
    return (doc, end, line, pending, number), max(-8.0, min(1.0, value))

"""A document-initial spelling detector with a small background approximation.

Hy followed by dro at the document's first two positions gives the largest
response; initial 1 + 2 also gives a positive response.  Initial token shape
supplies a coarse baseline.  Elsewhere, use small biases for grammatical
words, URL syntax, tool markup, and a subscript-like 2 following letters.
These rules leave most of the component's small lexical variation unexplained.
"""
READS = ()

# A few high-amplitude biases among English closed-class words.
FUNCTION_WORDS = {
    'it': -0.022, 'there': -0.040, 'been': -0.041,
    'must': 0.039, 'very': 0.051, 'but': -0.020,
    'some': -0.028, 'other': -0.024, 'while': -0.027,
    'because': 0.027, 'too': -0.044, 'am': -0.029,
}


def initial_value(token):
    text = token.strip()
    if not text:
        return -0.148
    if text.startswith('<|'):
        return -0.200
    if text.isdigit():
        return 0.125
    if text.isascii() and text.isalpha():
        if token.startswith(' '):
            return 0.126
        if text.islower():
            return 0.082
        if text.isupper():
            return -0.117
        return -0.025
    return -0.138 if text.isascii() else 0.044


def background(token, previous):
    if token.startswith(' '):
        word = token[1:]
        if word in FUNCTION_WORDS:
            return FUNCTION_WORDS[word]
    if token == '2':
        last = previous[-1:]
        if last.isupper():
            return 0.111
        if last.isalpha():
            return 0.044
        if last.isdigit():
            return -0.010
    if token == '://':
        return -0.111
    if token == '.com' and previous == 'github':
        return -0.350
    if token == 'www':
        return 0.108
    if token in ('<tool_call>', '</tool_call>'):
        return -0.062
    return 0.0003


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        position, previous = 0, ''
    else:
        _, position, previous = carry
    if position == 0:
        value = -0.2507 if token == 'Hy' else initial_value(token)
    elif position == 1 and previous == 'Hy' and token == 'dro':
        value = 1.2510
    elif position == 1 and previous == '1' and token == '2':
        value = 0.699
    else:
        value = background(token, previous)
    return (doc, position + 1, token), value

"""Approximate a negative response to written kh/ch and Cyrillic х.

The strongest cases are short root fragments, Slavic ch, and isolated kh.
Russian plural endings and common complete English/German words are weaker.
A short continuation after the spelling inherits a smaller response. The
recent text is only a bounded spelling/language cue, reset per document.
This is not a pronunciation parser: lexical exceptions remain unmodelled.
"""
import re
from functools import lru_cache
from wordfreq import zipf_frequency

READS = ()


@lru_cache(maxsize=8192)
def common_word(word):
    return max(zipf_frequency(word, 'en'), zipf_frequency(word, 'de')) >= 4


def slavic_spelling(text):
    text = text.lower()
    return (any(c in 'ěůřłąęśźżćťďňščž' for c in text)
            or re.search(r'\b(?:się|czy|jako|které|jsou|není)\b',
                         text) is not None)


def response(token, previous, recent):
    s = token.lower()
    w = s.strip()
    boundary = s[:1].isspace()
    if not w:
        return 0.0
    if 'х' in w or 'ch' in w or 'kh' in w or s == 'h':
        match = re.search(r'[^\W\d_]+$', recent.lower())
        word = match.group() if match else w
    else:
        word = w
    if 'х' in w:
        if w == 'х':
            if boundary:
                return -1.9
            if word.endswith('ях'):
                return -1.1
            if word.endswith('ах') and len(word) > 4:
                return -1.6
            if word.endswith(('их', 'ых')) and len(word) > 4:
                return -2.9
            return -4.0
        if w.endswith('х'):
            if boundary and w in ('их', 'них'):
                return -0.95
            if w.endswith('их'):
                return -4.0 if len(word) <= 5 else -2.6
            if w.endswith('ых'):
                return -2.3
            if w.endswith('ах'):
                return -4.8 if len(word) <= 4 else -1.6
            if w.endswith('ех'):
                return -2.9
            if w.endswith('ух'):
                return -3.9
            return -0.45
        return -0.4 if w.startswith('х') else 0.0
    if s == 'h' and previous.lower().endswith('k'):
        return 0.0 if previous.lower().endswith('ck') else -5.0
    if 'kh' in w:
        if w == 'kh':
            return -1.5 if boundary and not slavic_spelling(recent) else -4.5
        if w.endswith('ikh'):
            return -3.5
        return -1.0 if len(w) <= 3 else -0.1
    if 'ch' in w:
        slavic = slavic_spelling(recent)
        if w.endswith('ých'):
            return -4.5
        if word.endswith('ích') and zipf_frequency(word, 'vi') < 3.0:
            return -4.0
        if w.endswith('ych') and not w.endswith('psych'):
            return -2.4
        if slavic:
            if w.endswith('ch'):
                if len(w) > 4 and zipf_frequency(w, 'en') >= 4.0:
                    return -0.08
                if boundary and w == 'ch':
                    return -6.5
                return -5.0 if len(word) <= 4 else -4.0
            return -2.0 if len(w) <= 4 else -0.04
        if word.endswith(('sch', 'tch')):
            return -0.05
        if w.endswith('ch'):
            if boundary and common_word(w):
                return -0.08
            if w.endswith(('lich', 'isch')):
                return 0.0
            if zipf_frequency(word, 'en') >= 3.0:
                return -0.08
            return -0.5
        return -0.04
    if not boundary and s[:1].isalpha():
        if previous.lower().endswith('ch') and slavic_spelling(recent):
            return -1.25
        if previous.lower().endswith('х'):
            return -0.5
    if w.endswith(('еч', 'юч')):
        return 0.5
    if 'خ' in w:
        return -0.3
    if w in ('ヒ', 'ひ'):
        return -0.8
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, recent = '', ''
    else:
        _, previous, recent = carry
    token = prefix.token_strings[-1]
    recent = (recent + token)[-160:]
    value = response(token, previous, recent)
    return (doc, token, recent), value

programs.haiku:
"""Layer 1 MLP, down_proj component 802: a word-fragment detector with opposite signs.

Reads the current token, lowercased and without a leading space, and whether it starts a
new word (a leading space) or continues one (none):

- A German "j" word-start split off by itself ("j", "jen", "jung") right after an article
  ("der jenige", "die jungen"): strongly negative, about -8. The piece that continues that
  word ("igen", "ungen", "ene") is negative too, about -5.
- A "j" or "jen" fragment elsewhere: slightly negative, about -0.3 (jen, jung: -1.5).
- A word-internal loanword ending "aj", "aje", "agem", "aggio", "aż", Cyrillic "аж"
  (lang-age, part-aj-ată, масс-аж): positive, about +2.4.
- A word-internal "age", "ages", "ager", "gage" (lang-age, recycl-age): positive, about +1.0.
- Everything else: 0.

It carries one bit, whether the previous token opened such a German j-word; resets at
document boundaries.
"""
READS = ()

ARTICLES = {"der", "die", "das", "den", "dem", "des", "ein", "eine"}
J_START = {"j", "jen", "jung", "jug"}
J_WORD = {"jen", "jung", "jug", "joh"}
AJ_ENDINGS = {"aj", "aje", "ajes", "aja", "ajo", "agem", "aggio", "aggi", "agens", "agg", "aż", "аж"}
AGE_ENDINGS = {"age", "ages", "ager", "gage"}


def step(carry, prefix, upstream):
    raw = prefix.token_strings[-1]
    tok = raw.strip().lower()
    word_start = raw.startswith(" ")
    new_doc = len(prefix.document_ids) < 2 or prefix.document_ids[-2] != prefix.document_ids[-1]
    prev = "" if new_doc else prefix.token_strings[-2].strip().lower()
    if tok in J_START and prev in ARTICLES:
        return True, -8.0
    if carry and not word_start and not new_doc:
        return False, -5.0
    if tok in J_WORD:
        return False, -1.5
    if tok in J_START:
        return False, -0.3
    if not word_start and tok in AJ_ENDINGS:
        return False, 2.4
    if not word_start and tok in AGE_ENDINGS:
        return False, 1.0
    return False, 0.0

programs.sol:
"""A local spelling/typography approximation, not a topic detector.

Negative responses chiefly mark separately tokenized close vowels followed
by selected consonants in Thai, Greek and Indic writing. Thai tone marks can
intervene. There is also a response to split emoji and decorative symbols
following spaces, sometimes before their UTF-8 character is complete.
A few document-initial markers and repeated middle-dot filler are positive.
Negative amplitudes are conservative: these patterns explain only part of
the activation. Other text stays near zero.
"""
from functools import lru_cache
import unicodedata as ud
import regex
from anyascii import anyascii

READS = ()
INDIC = {'DEVANAGARI', 'BENGALI', 'GURMUKHI', 'GUJARATI',
         'ORIYA', 'TAMIL', 'TELUGU', 'KANNADA', 'MALAYALAM'}
THAI_TONES = frozenset('่้๊๋')


@lru_cache(maxsize=32768)
def describe(text):
    name = ud.name(text, '') if len(text) == 1 else ''
    return name.split(' ')[0], anyascii(text), name


def unfinished(data):
    """The unfinished UTF-8 character at the end, if any."""
    i = len(data) - 1
    while i >= 0 and 128 <= data[i] < 192:
        i -= 1
    if i < 0:
        return b''
    lead = data[i]
    size = 2 if 194 <= lead < 224 else 3 if 224 <= lead < 240 else 4
    return data[i:] if lead >= 194 and len(data) - i < size else b''


def new_emoji_block(fragment):
    # Three bytes suffice to identify this Unicode block, without guessing
    # the fourth byte or looking ahead to the next token.
    return len(fragment) == 3 and bool(regex.fullmatch(
        r'\p{Block=Supplemental_Symbols_And_Pictographs}',
        (fragment + b'\x80').decode('utf-8', 'ignore')))


def step(carry, prefix, upstream):
    raw, doc = prefix.token_bytes[-1], prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        tail, vowel, tone, age = b'', '', '', 0
    else:
        _, tail, vowel, tone, age = carry
    before = tail.decode('utf-8', 'ignore')
    text = (tail + raw).decode('utf-8', 'ignore')[len(before):]
    script, sound, name = describe(text)
    value = 0.0005

    if script == 'THAI':
        if text == 'น':                         # ordinary n
            if vowel == 'ุ' and tone:
                value = -3.1 if tone == '่' else -1.6
            elif vowel in ('ิ', 'ี', 'ุ', 'ู'):
                value = -1.25
            elif vowel == 'ั' and tone:
                value = -0.8
            elif vowel in ('ึ', 'ื'):
                value = -0.4
            else:
                value = -0.08
        elif text == 'ณ' and vowel in ('ุ', 'ู'):  # retroflex n
            value = -0.65 if vowel == 'ุ' else -1.3
        elif text == 'ม' and vowel in ('ิ', 'ี', 'ุ', 'ู'):  # m
            value = -0.8
        elif text == 'ธ' and vowel == 'ิ':       # th, as in วิธี
            value = -1.2
        elif sound in ('b', 't', 'd') and vowel in ('ิ', 'ี', 'ุ', 'ู'):
            value = -0.45
    elif script == 'GREEK':
        base = ud.normalize('NFD', vowel)[:1]
        if sound == 'th':
            if base == 'ι':
                value = -2.05
            elif vowel == 'ου':
                value = -1.3
            elif base == 'υ':
                value = -0.45
            elif base == 'η':
                value = -0.25
        elif sound == 'n' and (base == 'υ' or vowel == 'ου'):
            value = -0.16
    elif script in INDIC and vowel and 'LETTER' in name:
        if sound == 's':
            value = -1.8
        elif sound == 't' and not name.endswith('TTA'):
            value = -1.2
            if ud.category(vowel).startswith('L'):
                value = -2.5
        elif sound in ('n', 'm'):
            value = -0.8

    split = len(raw) == 1 and 128 <= raw[0] < 192
    if split and before.endswith(' '):
        old, new = unfinished(tail), unfinished(tail + raw)
        if new_emoji_block(new):
            value = -1.7
        elif not new_emoji_block(old) and len(text) == 1:
            if script == 'REGIONAL':            # first letter of a flag
                value = -1.0
            elif script == 'MAN':
                value = -2.4
            elif text in ('✗', '✖'):
                value = -0.55
            elif 'STAR' in name or 'NOTE' in name or name == 'SPARKLES':
                value = -1.8
            elif regex.fullmatch(r'\p{Emoji_Presentation}', text):
                value = -0.8

    if age == 0:
        if text == '--':
            value = 1.91
        elif text in ('def', 'class'):
            value = 1.7
        elif text == '@':
            value = 1.6
    if text == '··' and before.endswith('·'):
        value = 0.49                           # repeated middle-dot filler

    if text:
        if all(ch in THAI_TONES for ch in text):
            tone = text[-1]
        else:
            independent = name.partition(' LETTER ')[2] in (
                'I', 'II', 'U', 'UU', 'VOCALIC R', 'VOCALIC RR')
            close_indic = script in INDIC and sound in ('i', 'u', 'r') and (
                'VOWEL SIGN' in name or independent)
            close_greek = script == 'GREEK' and (
                ud.normalize('NFD', text)[:1] in ('ι', 'η', 'υ'))
            if (script == 'THAI' and text in 'ิีึืุูั') or (
                close_greek or text == 'ου' or close_indic):
                vowel = text
            else:
                vowel = ''
            tone = ''
    if value < 0:
        value *= 0.65
    return (doc, (tail + raw)[-16:], vowel, tone, age + 1), value

"""A lexical fruit/result detector, not a general food detector.

The negative response is strongest on 'fruit' and its frut-/fruct-/frukt-
relatives, especially when a token completes the root. Chinese 果 also means
result: its achievement and literal-fruit compounds respond strongly, while
'if', 'result', and 'effect' compounds respond more weakly. Vietnamese and
Korean have related fruit/result words. Small spelling echoes are included,
including a positive response when the letters quot- are completed.
Only the current word fragment is retained, and document boundaries reset it.
"""
import re
from anyascii import anyascii

READS = ()
FRUIT_ROOT = re.compile(r'fr(?:uit|ut|uc|uk|uch)|vrucht')
# Chinese words containing the fruit/result character; not names of fruits.
COMPOUNDS = {
    '如果': -0.35,  # if
    '结果': -0.9,   # result
    '結果': -1.1,   # result, traditional spelling
    '效果': -1.9,   # effect
    '成果': -6.5,   # achievement, fruits of work
    '果实': -6.5,   # fruit
    '水果': -4.9,   # fruit
    '果然': -4.2,   # as expected
    '后果': -4.5,   # consequence
}


def response(previous, token):
    word = token.strip()
    if '果' in token:
        for compound, value in COMPOUNDS.items():
            if compound in token:
                return value * (0.65 if len(word) > len(compound) else 1.0)
        return -4.6 if word == '果' else 0.0
    if word == 'quả':
        if previous.lower().endswith(('kết', 'ết')):
            return -0.7  # result
        return -2.7 if previous.lower().endswith('hiệu') else -6.0
    if word == 'trái':  # fruit (also 'left')
        return -4.3
    if word == '과':   # Korean fruit/result syllable, also a particle
        return -1.0
    if word.lower() in {'outcome', 'outcomes'}:
        return -0.6

    current = anyascii(token).lower()
    old = anyascii(previous).lower()
    if current.strip() in {'fruitful', 'fruition'}:
        return -0.6
    if current.strip().startswith('rezultat'):
        return -0.9
    if FRUIT_ROOT.search(current):
        return -6.0
    joined = old + current
    if any(m.end() > len(old) for m in FRUIT_ROOT.finditer(joined)):
        if 'fruit' in joined:
            return -11.9
        return -7.7 if re.search(r'fru[ck]', joined) else -4.6
    if current == 'ru' and old.endswith('f'):
        return -3.0  # The fru- beginning, before the root is complete.
    if current == 'ot' and old.endswith('qu'):
        return 1.35  # A positive spelling echo when quot- is completed.
    if FRUIT_ROOT.search(old) and current == ' of':
        return -3.2
    if not token[:1].isspace():
        if re.fullmatch(r'u(?:it|t|th)(?:s|e|es|a|as|o|os)?', current):
            if old.endswith(('r', 'f')):
                return -1.3 if current.startswith('ui') else -1.0
            if old.endswith('l'):
                return -0.2
        if current == 'und' and old.endswith('r'):
            return -1.2
        if current in {'uch', 'ucht'} and old.endswith('r'):
            return -0.3
    return -0.0016


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    value = response(previous, token)
    word_fragment = re.split(r'\s', previous + token)[-1][-24:]
    return (doc, word_fragment), value

