"""Approximate a local cel/sel/el spelling-fragment feature.

Short cel-like pieces are negative; el pieces depend on the preceding token's
last letters (c/s/z negative, h/i often positive). Spaces and longer endings
change the strength. French demonstratives and Excel have separate rules.
Transliteration extends some rules to Cyrillic and Greek; Japanese セル is
handled directly. This is not a detector for the meaning of biological cells.
Only the previous token is retained, resetting at document boundaries.
"""
from functools import lru_cache
from anyascii import anyascii
import re
import regex

READS = ()

@lru_cache(maxsize=32768)
def spelling(text):
    return anyascii(text).lower()


def predict(token, previous):
    s = spelling(token)
    p = spelling(previous)
    if not regex.fullmatch(
        r'[\p{Latin}\p{Cyrillic}\p{Greek}\p{Common}\p{Inherited}]*',
        token,
    ):
        return -5.3 if token == 'セル' else -0.002
    if token.endswith('ь'):
        s = s.rstrip("'")
    word = s.strip(' \t\r\n._-<>()[]"\'`/\\')
    value = -0.002
    if 'cancel' in s or 'accel' in s:
        return value
    if p.endswith('canc') and s.startswith('el'):
        return value
    if p.endswith(('cance', 'cancel')) and token[:1].islower():
        return value

    # Whole spellings whose cel syllable is particularly salient.
    if word in ('celui', 'celle', 'celles', 'ceux'):
        return -6.8 if word != 'ceux' else -3.6
    if word in ('cela', 'cele'):
        return -2.6
    if word in ('excel', 'excell'):
