        if p.endswith('ts'):
            value = -4.8
        elif last == 'c':
            value = -6.5 if p.endswith(('nc', 'sc')) else -4.4
        elif last == 's':
            value = -2.7
        elif last == 'z':
            value = -3.9
        elif last == 'x':
            value = -1.6
        elif last in ('k', 'g', 'j', 'u'):
            value = -0.45
        elif p.endswith(('ch', 'sh')):
            value = 0.15
        elif last == 'h':
            value = 1.7
        elif last == 'i':
            value = 1.25
        elif last == 'y':
