            return -8.0
        if len(p.strip()) > 2 and re.search(r'[csz]e$', p):
            return -4.5
    if s == 'iel':
        return -0.6 if p[-1:] in ('s', 'z', 'c') else (
            3.0 if p.endswith('h') else 0.9
