    elif token in {' `', ' ```'}:
        if first and token == ' `':
            value = -1.67
        elif '\n' in previous:
            value = -2.2
        elif token == ' ```':
            value = -0.52
        elif '\xa0' in previous:
            value = -0.95
        elif '`' in previous:
