def opening_value(token):
    word = token.strip()
    if len(word) == 1 and word in '0123456789':
        # Higher digits generally give a stronger pulse; zero is also strong.
        return -7.9 if word == '0' else -4.0 - 0.96 * int(word)
    if not word:
        if token == '\t':
            return -11.0
        return -4.5 if token.startswith('\n') else -2.8
    if '\ufffd' in word:
        return -0.3
    if word.startswith('<|'):
        return -4.6
    if regex.search(r'\p{Script=Han}', word):
        return -3.3 if len(word) == 1 else -5.5
    if not regex.search(r'\p{Script=Latin}', word):
        return -2.2
    if not word.isalpha():
        return -4.4
    # Capitalized person/place nouns are often names, with a stronger pulse.
    if len(word) > 2 and word.istitle():
        classes = set(wordnet.categories(word))
        if (classes & {'noun.person', 'noun.location'}
                and wordnet.parts_of_speech(word) == {'noun'}):
            return -12.7
    frequency = zipf_frequency(word.lower(), 'en')
    if word.lower() in {'a', 'an', 'the'}:
        return -7.5
    if len(word) <= 2:
        return -7.3 if frequency >= 7.3 else -4.9
    return -7.4 if frequency < 2.0 else -6.3


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_ids[-1]
    if carry is None or carry[0] != doc:
        value = opening_value(prefix.token_strings[-1])
        return (doc, token, value), value
    _, first_token, value = carry
    if token != first_token:
        value = 0.0
    return (doc, first_token, value), value

"""A perfect-construction detector with a few document/markup responses.

'Been' is strongest in 'should/must have been', weaker with other modals or
infinitival 'to have', and small in ordinary present/past perfect clauses.
After have, done/had/seen get a smaller scaled response.
