READS = ()
OBLIGATION = {'should', 'must'}
HYPOTHETICAL = {'would', 'could', 'might'}
ADVERBS = {'not', 'never', 'well', 'always', 'otherwise', 'probably', 'undoubtedly'}


def perfect_strength(words):
    """How strongly the preceding auxiliary suggests a nonfinite perfect."""
    if not words:
        return 0.0
    auxiliary = words[-1].replace('’', "'")
    if auxiliary.endswith("'ve"):
        modal = auxiliary[:-3]
        if modal in OBLIGATION | HYPOTHETICAL:
            return 1.5
    if auxiliary == 'having':
        return 0.9
    if auxiliary != 'have':
        return 0.16
    before = words[-2].replace('’', "'") if len(words) > 1 else ''
    before = before.removesuffix("n't")
    if before in OBLIGATION:
        return 3.0
    if before in {'will', 'shall'}:
        return 1.5
    if before == 'may':
        return 2.0
    if before in HYPOTHETICAL or before == 'to' or before in ADVERBS:
        return 2.3
    if before.endswith('ly') or not before:
        return 2.3
    if before in {'and', 'or'}:
        return 0.65
    return 0.16


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        text, position, previous = '', 0, ''
    else:
        _, text, position, previous = carry
    word = token.strip().lower()
    value = 0.0
    if word in {'been', 'done', 'had', 'seen'}:
        words = re.findall(r"[a-z]+(?:['’][a-z]+)?", text.lower())
        strength = perfect_strength(words)
        if word == 'been':
            value = strength
            if words == ['have'] and text.strip().lower() != 'have':
                value = 0.3
            if words and words[-1] == 'always':
                value = 0.65
            elif words and (words[-1].endswith('ly') or words[-1] == 'also'):
                value = max(0.5, 0.8 * perfect_strength(words[:-1]))
            if value > 1 and position < 12:
                value += 0.8
        elif words and words[-1] == 'have':
            value = strength * (0.65 if word in {'done', 'had'} else 0.45)
    if position == 1 and text == 'Title' and token == ':':
        value = 10.37
    elif position == 0:
        if token == 'def':
            value = 1.74
        elif token == '--':
            value = 1.75
        elif token == '..':
            value = 0.99
    interpuncts = len(token) > 1 and set(token) == {'·'}
    if interpuncts and (position == 0 or previous == token):
        value = 0.93
    if token == '!' and re.search(r'(?:^|\n)\s*>\s*\[$', text):
        value = 1.75
    elif re.search(r'\bassert$', text) and token.startswith(('!(', '_(')):
        value = 0.75
    return (doc, (text + token)[-160:], position + 1, token), value

"""A mostly locative 'in' detector, weaker for abstract grammatical uses.

Lowercase 'in' is positive, especially after birth/residence verbs. Changes,
results, references and inclusion weaken it; a loop's 'in' is negative.
Translations are disambiguated by recent words' language frequencies.
Slash-joined words also get a positive response, while other prepositions
get a small negative one. Document starts use a coarse character-class
baseline because their activations differ substantially from later tokens.
