import re
from functools import lru_cache
import wordnet
from wordfreq import zipf_frequency

READS = ()

# Lemmas grouped by the kind of complement their following 'in' takes.
LIFE = set('die live reside work travel arrive grow'.split())
COPULA = set('is are be was were been'.split())
CHANGE = set('increase decrease change difference reduction rise decline variation '
             'improvement error mistake gap result'.split())
REFERENCE = set('show describe define discuss illustrate mention specify report '
                'list indicate detail depict'.split())
INVOLVEMENT = set('include contain involve engage interest participate role'.split())
TRANSLATIONS = {'en': 0.23, 'em': 0.42, 'im': 0.25, 'в': 0.42,
                'w': 0.16, 'v': 0.06, 'în': 0.32, 'در': 0.32,
                'في': 0.15, 'فى': 0.38}


@lru_cache(maxsize=8192)
def frequency(word, language):
    return zipf_frequency(word, language)


def translated_in(word, text):
    """Disambiguate translations from English word fragments or variables.

    Recent words vote for a language by their dictionary frequencies.
    """
    words = re.findall(r"[^\W\d_]+", text.lower())[-12:]
    if not words:
        return 0.0
    candidates = {'en': ('es', 'fr', 'nl', 'en'), 'em': ('pt', 'en', 'vi', 'tr'),
                  'w': ('pl', 'en'), 'v': ('cs', 'sk', 'sl', 'en', 'vi', 'de')}[word]
    language = max(candidates, key=lambda lang:
                   sum(frequency(w, lang) for w in words))
    if word == 'en':
        return 0.60 if language == 'es' else -0.06 if language == 'fr' else 0.0
    locative_languages = {'em': {'pt'}, 'w': {'pl'},
                          'v': {'cs', 'sk', 'sl'}}
    if language in locative_languages[word]:
        return {'em': 0.73, 'w': 0.58, 'v': 0.35}[word]
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    start = carry is None or carry[0] != doc
    text = '' if start else carry[1]
    token = prefix.token_strings[-1]
    word = token.strip()
    boundary = (start or token[:1].isspace() or
                not text[-1:].isalnum())
    value = 0.0
    if (word.lower() == 'in' and boundary) or token.lower() == '-in':
        if word == 'In':
            value = 0.23
        elif word == 'IN':
            value = 0.27
        else:
            value = 0.43
            previous = re.search(r'(\w+)\W*$', text)
            previous = previous[1].lower() if previous else ''
            lemmas = set(wordnet.base_forms(previous)) | {previous}
            if previous == 'born':
                value = 0.92
            elif lemmas & LIFE:
                value = 0.74
            elif previous in COPULA or previous in {'up', 'back'}:
                value = 0.56
            elif lemmas & CHANGE:
                value = 0.02
            elif lemmas & REFERENCE:
                value = 0.10
            elif lemmas & INVOLVEMENT:
                value = 0.14
            elif previous == 'used':
                value = 0.24
            if re.search(r'\b(?:for|foreach)\b[^\n;:]{1,45}$', text):
                value = -0.15
            if text.endswith('\\'):
                value = -0.12
    elif word in TRANSLATIONS and boundary:
        value = TRANSLATIONS[word]
    elif word == 'В':
        value = 0.35
    elif word.lower() in {'on', 'at', 'from', 'through', 'upon', 'off'} and boundary:
        value = -0.07
    if word in {'en', 'em', 'w', 'v'} and boundary and not start:
        value = translated_in(word, text)
    # A slash joining ordinary words, not a URL or a path, also excites it.
    if token.startswith('/') and token[1:].isalpha():
        last_word = text.rsplit(None, 1)[-1] if text.strip() else ''
        if len(last_word) > 2 and last_word.isalpha():
            value = 0.70
    if start:
        if word.isdigit():
            value = 0.03
        elif token.isalpha():
            value = max(value, 0.43)
        elif token.startswith(' ') and word.isalpha():
            value = max(value, 0.26)
        elif token.startswith('<|'):
            value = 0.44
        else:
            value = max(value, 0.14)
    return (doc, (text + token)[-160:]), value

