    (('shale',), -4.8),
    (('shalt',), -6.8),
    (('shallow',), -1.7),
    (('shalk', 'shoal', 'shoals'), -6.5),
    (('sholl', 'shaling'), -5.0),
    (('shark', 'sharks'), -2.3),
    (('shak',), -3.5),
    (('shank',), -1.8),
    (('shelf', 'shelves'), 1.3),
    (('shade', 'shades'), 4.4),
    (('shaded',), 3.1),
    (('shading', 'shady'), 1.5),
    (('shaw', 'shawl'), -3.5),
