        return -10.0 if split else -8.2
    if word.endswith(('shal', 'shals')):
        if word.endswith('unmarshal'):
            return -1.0
        if split and token.lower() in {'al', 'als'}:
            return -11.5
        return -2.5 if word == 'marshal' and spelling.islower() else -5.4
    for endings, value in SPELLING_FAMILIES:
