    if split and word.endswith('shaker'):
        return -4.2
    if split and word.endswith(('sheath', 'sheathing')):
        return 3.2
    if word == 'ska':
        return -3.0 if split else -8.0
    if word.endswith('skal'):
        return -6.8
    if word == 'skulle':
        return -4.3
    if word in GERMAN_MODALS:
