    if word.endswith('should'):
        return 0.0 if first_person else -0.9 if token.startswith(' ') else -1.7
    if word == 'not' and previous == 'shall':
        return -3.0
    if word == 'of' and previous.endswith(('shade', 'shades')):
        return 5.0
    if word == 'sha1':
        return -5.5
    if word == 'hall':
        return -0.7
    if split and token.lower() in {'al', 'als', 'all', 'hal'}:
        if previous.endswith('fh') and token.lower() == 'all':
            return -9.5  # Historical long-s printed as f: "fhall".
        if previous.endswith(('ch', 'ph', 'sh', 'sk')):
            return -3.5
        if token.lower() == 'hal' and previous.endswith('st'):
            return -4.0
        if token.lower() == 'all' and previous.endswith('th'):
            return -4.5
    if split and token.lower() == 'ka' and previous.endswith('sh'):
        return -2.5
    return -0.2 if start else 0.0


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    start = carry is None or carry[0] != document
