    word = normalize(spelling)
    token = raw.decode('utf-8', errors='ignore')
    split = bool(previous and token and token[0].isalnum()
                 and len(word) > len(normalize(token)))
    value = amplitude(word, previous, spelling, token, split, start)
    return (document, buffer, word), value

