# Columns: English Zipf frequency <1, 1–3, 3–4, 4–5, and >=5.
H_PIECE = (-0.0435, 0.0372, 0.0102, 0.0018, -0.0356)
# Rows: first, second, and later continuations of an H piece.
CONTINUATION = (
    (-0.0743, -0.2041, -0.0676, 0.1381, 0.1775),
    (-0.1199, -0.4663, -0.3702, -0.316, -0.0618),
    (-0.0037, -0.0199, -0.3235, -0.0042, 0.0),
)
# Lengths 1, 2, 3, 4, and 5 or more characters.
PREFIX_LENGTH = (0.2002, -0.0836, -0.1417, -0.0702, 0.0462)
H_FUNCTION_WORDS = frozenset((
    'he', 'her', 'hers', 'herself', 'him', 'himself', 'his',
    'have', 'has', 'had', 'having', 'how', 'however', 'hence',
))
QUESTION_AUXILIARIES = frozenset((
    'is', 'are', 'was', 'were', 'do', 'does', 'did', 'can', 'could',
))


@lru_cache(maxsize=50000)
def spelling(token):
    text = anyascii(token).lower().lstrip(' \t\r\n._-/\\"\'([{')
    match = re.match('[a-z]+', text)
    return match.group() if match else ''


@lru_cache(maxsize=50000)
def frequency_band(word):
    frequency = zipf_frequency(word, 'en') if word else 0.0
    return (0 if frequency < 1 else 1 if frequency < 3 else
            2 if frequency < 4 else 3 if frequency < 5 else 4)


