        value += CONTINUATION[depth - 1][band]
        if depth == 1:
            value += PREFIX_LENGTH[min(len(word), 5) - 1]
            if previous.lstrip()[:1].isupper():
                value -= 0.4376
    if last_h and token[:1].isspace() and not h:
        value -= 0.0205
    if previous.strip() in ('How', 'how'):
        if token.strip() in QUESTION_AUXILIARIES:
            value -= 0.4003
            if token.strip() in ('is', 'are', 'was', 'were'):
                value -= 2.1847
            if position == 1:
                value -= 2.1074
    if token.isdecimal():
        if previous == '7':
            value -= 0.0205
        if two_back == '7':
            if previous.isdecimal():
                value -= 1.1218
                if token == '7':
                    value += 0.6814
            elif previous == '.':
                value -= 0.1733
            elif previous == ',':
                value -= 0.0539
    age = 1 if h else min(age + 1, 4) if age and continuation else 0
    carry = (document, token, previous, whole[-32:], age,
             h, last_h, position + 1, first_h)
    return carry, float(value)

programs.haiku:
"""Layer-1 MLP down_proj component 815: a detector for a few specific spots in text.

It is almost always near zero. It goes strongly negative at:
  1. the third digit of a number that starts with 7 (the "6" of 76x): about -1.2;
  2. a later piece of a word that begins with H, as in Hu|am|n or Her|zen|stein:
     about -0.4, and -1.6 for "am" after "Hu" (the split word "Human");
  3. the auxiliary right after the question word "How" (How [is], How [are], How [can]).
"""

READS = ()

DIGITS = set("0123456789")
HOW_AUX = {"is": -3.4, "are": -3.1, "can": -1.0, "would": -0.9, "did": -0.7}


def _is_piece(tok):
    # a piece of a word: letters or digits with no leading space
    return tok[:1] not in (" ", "\n", "\t") and tok.isalnum()


def step(carry, prefix, upstream):
    t = prefix.position
    toks = prefix.token_strings
    docs = prefix.document_ids
    cur = toks[t]
    if t == 0 or docs[t - 1] != docs[t]:
        return None, 0.0
    value = 0.0

    # 1. Third digit of a number that starts with 7.
    if cur in DIGITS:
        k = t
        while k > 0 and docs[k - 1] == docs[t] and toks[k - 1] in DIGITS:
            k -= 1
        if t - k == 2 and toks[k] == "7":
            value = -1.2

    # 2. A later piece of a word that starts with H.
    if _is_piece(cur) and not cur.isdigit():
        k = t
        while k > 0 and docs[k - 1] == docs[t] and _is_piece(toks[k]):
            k -= 1
        if k < t and toks[k].strip()[:1] in ("H", "h"):
            value = -1.6 if (cur == "am" and toks[t - 1].strip() == "Hu") else -0.4

    # 3. The auxiliary right after "How".
    if toks[t - 1].strip().lower() == "how" and cur.strip() in HOW_AUX:
        value = HOW_AUX[cur.strip()]
    return carry, float(value)

programs.sol:
"""Approximate a mathematical expression-boundary signal.

A TeX backslash following an operand is usually negative; one beginning
an expression is positive. Spaces, prose, and escaped source code weaken
that signal. Closing math dollars, split TeX commands, and incomplete
Unicode punctuation have smaller rules. Other tokens get nearly zero.
Only the most recent 160 decoded characters are retained.
"""
import re
from functools import lru_cache
from wordfreq import zipf_frequency

READS = ()
RELATIONS = set('''in notin ni subset supset subseteq supseteq
le leq ge geq ne neq equiv approx sim simeq cong propto to mapsto
rightarrow leftarrow implies iff vdash models mid perp parallel
pm mp times cdot div cup cap land lor wedge vee'''.split())
STYLES = set('''displaystyle textstyle scriptstyle scriptscriptstyle
begin end item'''.split())
GREEK = set('''alpha beta gamma delta epsilon varepsilon zeta eta theta
vartheta iota kappa lambda mu nu xi omicron pi varpi rho varrho sigma
varsigma tau upsilon phi varphi chi psi omega Gamma Delta Theta Lambda
Xi Pi Sigma Upsilon Phi Psi Omega'''.split())
MATH_COMMANDS = GREEK | RELATIONS | STYLES | set('''frac sqrt sum prod int
lim sin cos tan cot log ln exp min max inf sup vec hat bar overline
underline boldsymbol partial ell nabla hbar big bigg left right quad
qquad cdots ldots dots mbox text setminus'''.split())
FUNCTION_WORDS = set('of by is in to for that be as at are or and the'.split())

# Responses to an adjacent backslash and a space-prefixed backslash.
SLASH_LEVELS = {
    'greek': (-5.0, -2.7), 'letter': (-4.0, -3.0),
    'number': (-3.1, -2.3), 'word': (-3.1, -2.6),
    'command': (-2.0, -1.3), 'style': (-1.4, 0.9),
    'relation': (-1.4, 0.9), 'close': (-2.0, -2.3),
    'paren': (4.0, 1.4), 'brace': (1.3, 1.3),
    'dollar': (3.4, 3.4), 'operator': (1.1, 1.1),
    'newline': (0.6, 0.6),
}


@lru_cache(maxsize=4096)
def prose_word(word):
    return (word.lower() in FUNCTION_WORDS or
            (len(word) > 2 and word not in MATH_COMMANDS and
             zipf_frequency(word.lower(), 'en') >= 3.5))


def boundary(tail):
    if not tail:
        return 'start'
    if tail.endswith('\n'):
        return 'newline'
    if tail[-1].isspace():
        return 'space'
    command = re.search(r'\\([A-Za-z]+)$', tail)
    if command:
        word = command[1]
        if word in STYLES:
            return 'style'
        if word in RELATIONS:
            return 'relation'
        return 'greek' if word in GREEK else 'command'
    c = tail[-1]
    if c.isdigit():
        return 'number'
    if c.isalpha():
        word = re.search(r'[A-Za-z]+$', tail)
        if word and prose_word(word[0]):
            return 'prose'
        return 'letter' if word and len(word[0]) == 1 else 'word'
    if c in '{[(':
        return 'brace' if c == '{' else 'paren'
    if c in '})]' or (c == '|' and re.search(r'[\w})\]]\|$', tail)):
        return 'close'
    if c in '=+-*/<>:|&^_':
        return 'operator'
    return 'dollar' if c == '$' else 'punct'


def activation(s, b, tail, prev):
    group = boundary(tail)
    commands = re.findall(r'\\([A-Za-z]+)', tail)
    tex = any(w in MATH_COMMANDS or w.startswith('math') for w in commands)
    opened = bool(re.search(r'\\[([]', tail))
    math = tex or opened or '$' in tail or bool(re.search(
        r'(?:[_^]\w+|[A-Za-z])\s*=\s*[-+]?\d', tail))
    code = bool(re.search(r'\\[nt"\']', tail)) and not (tex or opened)
    if group == 'space' and math:
        group = boundary(tail.rstrip())
    start_formula = bool(re.search(
        r'\\[([]\s*$|\\begin\{(?:align\*?|aligned|equation\*?|eqnarray\*?)\}\s*$',
        tail))
    if s in ('\\', ' \\', '\\t'):
        if code or (s == '\\t' and not math):
            return -0.15
        if start_formula:
            return 3.4
        if group == 'start':
            return -1.0
        if group in ('letter', 'word') and not math:
            return -0.2
        if group == 'close' and not math:
            return -0.3
        if s == '\\t' and group == 'number':
            return -4.3  # The beginning of TeX's multiplication command.
        return SLASH_LEVELS.get(group, (0.0, 0.0))[s.startswith(' ')]
    if s.endswith('\\') and s.count('\\') == 1:
        before = s[:-1].strip()
        if code:
            return -0.05
        if before in ('}', ')', ']'):
            if re.search(r'\\begin\{[A-Za-z*]+$', tail):
                return 0.3
            return (-1.7 if group == 'greek' else -2.6) if math else -0.2
        if before == '{':
            return 1.2 if group == 'operator' else 0.3
        if before in ('(', '['):
            return 0.7 if group == 'command' else (1.6 if math else 0.1)
        if before in ('^', '_', '+', '-', '='):
            return 0.65
        if before == '$':
            return 1.0 if group == 'newline' else 0.65
    if s in ('$', '$$', '}$', ')$', ']$'):
        if code:
            return 0.0
        if group in ('letter', 'greek'):
            return -1.5 if s == '$' else -0.85
        if group == 'number':
            return -1.2 if s == '$' else -0.75
        if group in ('word', 'command', 'close'):
            return -0.7 if s != '$$' else -0.4
        return 0.2 if group == 'newline' else -0.1
    if b.lstrip(b' ') in (b'\xe2', b'\xe2\x80', b'\xe2\x81',
                         b'\xe2\x88', b'\xe2\x89', b'\xe2\x8a'):
        return -0.85 if group in ('letter', 'number') else (
            -1.1 if group == 'close' else -0.1)
    if s == ' â' and group in ('letter', 'number', 'close'):
        return -1.5  # A common mojibake prefix of mathematical symbols.
    # Visible beginnings of rfloor, mapsto, big, wedge, vee, left, right.
    if prev.strip() == '\\' and not code:
        if s in ('rf', 'map'):
            return -5.5 if s == 'rf' else -4.2
        if s in ('big', 'w', 've') and math:
            return -2.0
        if s in ('right', 'left'):
            return -0.85 if s == 'right' else -0.35
    if s in ('g', 'gr') and tail.endswith('\\big'):
        return -3.2  # Further pieces of bigg/biggr delimiter commands.
    if s == '^{' and math:
        return 0.55
    if s == '{' and tail.endswith('\\text'):
        return -1.3
    return -0.003


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        tail, prev = '', ''
    else:
        _, tail, prev = carry
    s = prefix.token_strings[-1]
    value = activation(s, prefix.token_bytes[-1], tail, prev)
    return (doc, (tail + s)[-160:], s), value

