        return 0.16 if token.startswith(' ') else -0.34
    if lower in DEMONSTRATIVES:
        return -0.30 if token.startswith(' ') else -0.65
    if not token.startswith(' '):
        if lower in IMPORT_WORDS:
            return -1.0
        if word == 'def':
            return -2.1
        if word == 'int':
            return -1.4
    if word in {',', ':', ';'}:
        return -0.25
    if word.isascii() and word.isdigit():
        return 0.06
    if any('CJK UNIFIED' in unicodedata.name(c, '') for c in word):
        return 0.23
    if not word:
        return -0.12
    return -0.10 if word.istitle() else 0.0


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, 0, '', '', 0, None, '')
    _, age, first, previous, roles, header_start, tail = carry
    if token == '<|im_start|>' and header_start is None:
        header_start = age
    stripped = token.strip()
    value = opening_value(token) if age == 0 else 0.001

    if stripped and set(stripped) == {'#'}:
        if age == 0:
            value = 0.23
        elif len(stripped) >= 3:
            value = -0.23 if previous.endswith('\n\n') else -0.10
        elif len(stripped) == 2:
            value = -0.06
    if age > 0 and stripped == '!':
        unfinished = previous.strip().lower() in (ARTICLES | PREPOSITIONS)
        value = 0.25 if unfinished else -0.025
    if stripped == '··':
        value = 0.375
    if token == 'assistant' and (age == 0 or previous == '<|im_start|>'):
        distance = age - header_start if header_start is not None else 0
        value = -0.90 if age == 0 else -0.10 - 0.08 / (
            1 + 0.5 * roles + distance / 64
        )
        roles += 1
    elif previous == 'assistant' and token == '\n':
        value = 0.033
    elif token == ' Okay' and previous == '\n' and '<think>\n' in tail[-10:]:
        value = -0.16

    if '\n' in token and not stripped:
        line = tail.rsplit('\n', 1)[-1].strip()
        math_question = '?' in tail or 'Calculate' in tail or 'Let ' in tail
        if NEGATIVE_INTEGER.fullmatch(line) and math_question:
            value = -1.6
    if age == 1 and first == 'Title' and token == ':':
        value = 12.795
    elif age == 1 and first == '1' and token == '2':
        value = -2.419
    if age == 0:
        first = token
    tail = (tail + token)[-240:]
    return (doc, age + 1, first, token, roles, header_start, tail), value

"""Orthographic seams: incomplete Unicode characters and vowel-initial words.

The largest positive predictions are made when a token starts another diacritic in
pointed Hebrew/Arabic, or splits a word-initial polytonic Greek character.
Most ordinary text gets zero. These rules also cover split emoji and a few
other scripts, accented Greek continuations, and Vietnamese vowel onsets.
Only a short byte tail and the preceding token are carried between steps.
This is a partial approximation, not an account of all component activity.
"""
import unicodedata as ud

READS = ()


def vietnamese(text):
    return any(c in text for c in 'đĐăĂơƠưƯ') or any(
        c in ud.normalize('NFD', text) for c in '\u0309\u0323')


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        tail, previous, position = b'', b'', 0
    else:
        _, tail, previous, position = carry
    b = prefix.token_bytes[-1]
    before = tail.decode('utf8', 'ignore')
    last = before[-1:]
    s = b.decode('utf8', 'ignore')
    value = 0.0

    # Bare lead bytes: another mark, or a non-Western digit, is starting.
    if b == b'\xd6':  # Hebrew points and cantillation
        value = 17.2 if last and ud.category(last).startswith('M') else -0.35
    elif b == b'\xd9':  # Arabic points and Arabic-Indic digits
        if last == 'ى' or (last and ud.category(last).startswith('M')):
            value = 11.4
        elif last.isspace() or last.isdigit():
            value = 6.2
        else:
            value = 1.2
    elif b == b'\xdb':  # Persian digits and Arabic extended marks
        value = 4.6 if last.isspace() else 3.5
    elif b == b'\xcc':  # combining diacritics
        if last and last.isalpha() and not last.isascii():
            value = 3.5  # phonetic and foreign-letter diacritics
        elif last.isdigit():
            value = 1.4
        else:
            value = 2.5 if last and last.lower() in 'aeiou' else 0.3
    elif b == b'\xe0\xb9':  # Thai marks/digits
        value = 3.5 if last.isspace() else -0.2

    # The middle of a character split after a space-prefixed lead byte.
    if previous in (b' \xea', b' \xeb', b' \xec', b' \xed') and len(b) == 1:
        value = 0.7  # split Hangul syllables
    elif previous == b' \xe0' and b in (b'\xbc', b'\xbd', b'\xbe'):
        value = 2.1 if b == b'\xbc' else 5.2  # Tibetan
    elif previous == b' \xe1' and b == b'\xbe':
        value = 3.8  # Greek extended diacritics
    elif tail.endswith(b' \xe1\xbe') and b == b'\xbf':
        value = 9.0  # Greek smooth breathing mark
    elif tail.endswith(b' \xe1\xbf') and b == b'\xbe':
        value = 8.5  # Greek rough breathing mark
    elif previous == b' \xe1' and b in (b'\xbc', b'\xbd'):
        value = 2.0  # polytonic Greek
    elif previous == b' \xe1' and len(b) == 1:
        value = 3.0 if b == b'\xb8' else 1.0  # extended Latin / Ethiopic
    elif previous == b' \xf0\x9f' and len(b) == 1:
        value = 0.95  # emoji and regional-indicator flags
    elif previous == b' \xef' and b == b'\xbe':
        value = 0.8  # halfwidth Japanese
    elif previous == b' \xc5' and len(b) == 1:
        value = 0.17 if b == b'\xbf' else 1.0  # extended Latin; long s is weaker
    elif previous == b'\xe0' and b == b'\xbe':
        value = 11.3  # Tibetan marks and subjoined letters

    # Completed diacritics and flag letters, still split across tokens.
    if len(b) == 1 and b[0] >= 128:
        completed = (tail[-4:] + b).decode('utf8', 'ignore')[-1:]
        name = ud.name(completed, '') if completed else ''
        if previous == b'\xd6':
            if name == 'HEBREW POINT METEG':
                value = 9.0
            elif name.startswith('HEBREW ACCENT'):
                value = 1.3
        elif previous == b'\xcc':
            if name == 'COMBINING VERTICAL LINE ABOVE':
                value = 4.1
            elif name == 'COMBINING CARON':
                value = 2.8
        elif name.startswith('REGIONAL INDICATOR SYMBOL') and len(previous) == 1:
            value = 1.0

    # Greek vowel combinations at token boundaries.
    if s == 'τ':
        if last == 'ί':
            value = -1.5
        elif last in 'ήόέ' and len(previous) == 1:
            value = -2.1
    elif s in ('ι', 'υ') and tail.endswith(b' \xce\xbf'):
        value = 1.1
    elif s == 'λ' and previous in (b'\xae', b'\x97'):
        value = -1.2

    # Vietnamese accented vowels starting a word without their usual merge.
    word = s.lstrip()
    if word and vietnamese(before + word):
        decomposed = ud.normalize('NFD', word[0])
        if len(decomposed) > 1 and decomposed[0].lower() in 'aeiouy':
            if s.startswith(' ') and word in ('áp', 'ép'):
                value = -1.8  # closed accented-vowel syllables
            elif not s.startswith(' ') and last and not last.isalpha():
                value = -2.6

    # Document-initial number/punctuation and filename-markup cues.
    if position == 1 and previous == b'1' and b == b'2':
        value = 2.075
    elif position == 0 and b == b'--':
        value = 3.14
    elif previous == b'<' and b == b'filename':
        value = 4.7

    return (doc, (tail + b)[-96:], b, position + 1), value

programs.haiku:
"""layers.1.mlp.down_proj:828 — the "reduced clause predicate" detector.

The component fires on the predicate of an adverbial clause whose subject and
verb have been dropped, the kind of clause a writer shortens to "if possible",
"when used", "unless requested", "as required", "where necessary".
Examples: "...when [appropriate]", "...if [applicable]", "...when [eaten]",
"...unless explicitly [requested]", "...as [shown] in Fig. 2".

Rule:
  * a word that is a predicate (a past participle ending in -ed, an -able/-ible
    adjective, a common irregular participle, an -ly adverb, or a short list of
    predicate adjectives such as possible/necessary/needed) directly after a
    clause opener fires strongly. "if", "when", "whenever", "unless", "where"
    count as strong openers; "as", "once", "until", "though", "although" as weak
    ones. "if not X" counts as "if X".
  * an -ly adverb between an opener and the predicate ("unless explicitly
    requested") passes the opener's strength on to the predicate.
  * the comma or preposition that follows such a predicate fires weakly.
  * everything else predicts 0.

Values are fitted to the component's mean activation in each case.
"""
import re

READS = ()

STRONG_OPENERS = {"if", "when", "whenever", "unless", "where", "wherever"}
WEAK_OPENERS = {"as", "once", "until", "though", "although"}
OPENERS = STRONG_OPENERS | WEAK_OPENERS
IRREGULAR_PARTICIPLES = {
    "eaten", "taken", "given", "known", "written", "done", "made", "seen", "set", "read",
    "held", "found", "shown", "sent", "put", "built", "born", "chosen", "driven", "fed",
    "kept", "led", "left", "lost", "paid", "run", "spoken", "told", "thought",
    "understood", "used",
}
PREDICATE_ADJECTIVES = {
    "possible", "necessary", "applicable", "appropriate", "available", "relevant",
    "true", "so", "correct", "ripe", "desired", "required", "needed", "requested",
    "herein", "ready", "safe", "sure",
}
FOLLOWERS = {",", "in", "to", "by", "from", "on", "with", "for"}


def _word(text):
    return text.strip().lower()


def _is_predicate(word):
    if not re.fullmatch(r"[a-z]+", word):
        return False
    return (word.endswith(("ed", "able", "ible", "ly"))
            or word in IRREGULAR_PARTICIPLES or word in PREDICATE_ADJECTIVES)


def _opener_strength(word):
    if word in STRONG_OPENERS:
        return 4.0
    if word in WEAK_OPENERS:
        return 1.4
    return 0.0


def step(carry, prefix, upstream):
    strings, docs = prefix.token_strings, prefix.document_ids
    n = len(strings)

    def word_back(k):
        # the lowercased token k places back, or "" across a document boundary
        if n < k + 1 or docs[-1 - k] != docs[-1]:
            return ""
        return _word(strings[-1 - k])

    cur, prev, prev2, prev3 = word_back(0), word_back(1), word_back(2), word_back(3)

    # "if [it is] possible" / "if not [it is] provided"
    opener = prev if prev in OPENERS else (prev2 if prev == "not" else "")
    if opener and _is_predicate(cur):
        return carry, _opener_strength(opener)

    # "unless [explicitly] requested": an -ly adverb between opener and predicate
    if prev.endswith("ly") and prev2 in OPENERS and _is_predicate(cur):
        return carry, _opener_strength(prev2)

    # the comma or preposition right after the predicate
    if cur in FOLLOWERS and _is_predicate(prev):
        head = prev2 if prev2 != "not" else prev3
        if head in OPENERS:
            return carry, 0.5 * _opener_strength(head)

    return carry, 0.0

programs.sol:
"""A spelling-boundary detector with a Vietnamese spatial-word response.

Positive responses mark u-o continuations, excluding silent u after q and
u-o-u sequences (as in -uous endings), and short tru/dru continuations.
Vietnamese spatial and possessive words give negatives after recent
Vietnamese letter or word cues.
Additional rules cover au/ua, repeated middle dots, and document-initial
code declarations, delimiters, or Title: labels. Everything else is zero.
State tracks spelling, the unfinished word, language recency and position.
"""
import re
from functools import lru_cache
import unicodedata

READS = ()

# Vietnamese location, direction, boundaries, and possession.
VIET_SPATIAL = {
    'sau': -5.8,      # after / behind
    'trước': -4.4,    # before / in front
    'trên': -4.5,     # above / on
    'dưới': -4.3,     # below / under
    'trong': -3.2,    # in / inside
    'ngoài': -5.2,    # outside
    'giữa': -5.0,     # between / middle
    'của': -2.4,      # of / belonging to
    'đầu': -2.8,      # head / beginning
    'cuối': -4.0,     # end / last
    'trái': -2.7,     # left
    'gần': -1.6,      # near
    'từ': -1.0,       # from
    'qua': -0.8,      # across / through
    'đây': -1.0,      # here
    'tr': -2.0,       # incomplete onset of several spatial words
}


@lru_cache(maxsize=8192)
def unaccent(s):
    s = s.lower().replace('đ', 'd')
    return ''.join(c for c in unicodedata.normalize('NFD', s)
                   if not unicodedata.combining(c))


@lru_cache(maxsize=8192)
def has_vietnamese(s):
    return any(0x1EA0 <= ord(c) <= 0x1EF9 or c in 'ăđơưĂĐƠƯ' for c in s)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', '', 0, 0)
    _, previous, word, vietnamese, position = carry
    s = prefix.token_strings[-1]
    plain = unaccent(s)
    if has_vietnamese(s):
        vietnamese = 96
    else:
        vietnamese = max(0, vietnamese - 1)
    match = re.search(r'[^\W\d_]+$', word + s.lower())
    word = match.group()[-32:] if match else ''
    if word in {'thêm', 'và', 'nào', 'các', 'không', 'những', 'này'}:
        vietnamese = 96

    value = 0.0
    if not vietnamese:
        if plain.startswith('uo') and not plain.startswith('uou'):
            value = 3.2
        elif (plain.startswith('o') and previous.endswith('u')
              and not previous.endswith('qu')):
            if plain.startswith('ou'):
                value = 0.0
            elif plain.startswith(('on', 'or', 'ov')):
                value = 0.9
            else:
                value = 3.2
        elif plain in ('u', 'uy', 'ui') and previous.endswith(('tr', 'dr')):
            value = 1.0
        elif s.lower() == 'ру' and previous.strip() == 'т':
            value = 1.8
        elif plain == 'ru' and previous.endswith('d'):
            value = 0.7
    if plain in ('au', 'ua'):
        value = -0.2
    if vietnamese and word in VIET_SPATIAL:
        value = VIET_SPATIAL[word]
    if len(s) >= 2 and s[0] == '·' and not s.strip('·'):
        value = -0.6
    if position == 0 and s.strip() in ('(', ')'):
        value = -0.5
    if position == 0 and s == '{':
        value = -1.27
    # Code declarations at the start of a document.
    if position == 0 and s == 'def':
        value = 3.60
    if position == 0 and s == 'var':
        value = -1.23
    if position == 1 and previous == 'title' and s == ':':
        value = -5.05
    return (doc, plain, word, vietnamese, position + 1), value

"""A surface approximation to a sparse Chinese clause/date and formatting signal.

Dates introducing a clause, purpose clauses beginning with 为/為, and formal
notice vocabulary receive negative values. Year and Japanese-script context
soften the date response. A few formatting and grammatical categories account
for additional, separate responses. Most words remain near zero; their individual
lexical effects, including rare positive subword spikes, are not modeled.
"""
import math
import re
import regex

READS = ()
RECENT = {'近日', '日前', '近期'}
PURPOSE = re.compile(r'[为為](?:了|进一步|進一步)?$')
PART_DAY = re.compile(r'(?:日)?(?:上午|下午|晚上|晚|早|凌晨|中午)$')
PROVISION = re.compile(r'第[一二三四五六七八九十百0-9]+[条條章款]$')
PACKAGES = {'util', 'lang', 'widget', 'apache', 'io', 'net', 'awt', 'swing'}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    s = prefix.token_strings[-1]
    w = s.strip()
    if carry is None or carry[0] != doc:
        carry = (doc, 0, '', 0., 0., False)
    _, pos, prev, year, japanese, date_clause = carry
    pw = prev.strip()
    initial = pos == 0
    period = bool(re.search(r'[。！？\n]$', prev))
    clause = initial or bool(re.search(r'[\n，。；：！？,;:]$', prev))
    digit = bool(pw) and pw[-1].isdigit()
    blank = bool(prev) and prev.isspace()
    # Preserve the clause-opening flag through a numeral/month/day sequence.
    date_clause = date_clause or initial or bool(
        re.search(r'[\n。；：！？]$', prev))
    value = -0.002

    if w == '年':
        value -= 0.06
    if w in ('月', '日'):
        if w == '月':
            value += -0.35 * digit + 0.12 * year + 0.07 * japanese
        else:
            value += -0.04 - 0.23 * digit + 0.14 * year + 0.06 * japanese
        value -= 0.31 * date_clause
    if w in ('时', '時', '分', '秒') and digit:
        value -= 0.05
    if PART_DAY.fullmatch(w):
        value -= 0.13 + 0.98 * w.startswith('日')
    if w in RECENT:
        value -= 0.33
    if w == '下一步':
        value -= 0.26
    if PURPOSE.fullmatch(w):
        value -= 0.24 * clause + 0.50 * period + 0.42 * blank
        value -= 0.15 * bool(re.search(r'[，,]$', prev))
    if w.lstrip('，。；') in {'请', '請', '须', '須', '必须', '必須', '应当', '應當'}:
        value -= 0.09
    # Administrative requirements, enrollment, and numbered provisions.
    if w in {'条件', '條件', '要求', '事项', '事項'}:
        value -= 0.12 + 1.20 * (pw in {'申请', '申請'})
    if w in {'报名', '報名', '报考', '報考'}:
        value -= 0.94
    if w in {'考生', '准考证', '準考證'}:
        value -= 0.38
    if w in {'申请', '申請'}:
        value -= 0.20
    if w in {'公告', '通知'}:
        value -= 0.33
    if PROVISION.fullmatch(w):
        value -= 0.53
    if w in {'时间', '時間', '时间为', '時間為', '日期', '期限', '截止'}:
        value -= 0.06 + 0.76 * (w in {'时间为', '時間為'})
    if w == '，' and pw in RECENT:
        value -= 0.73
        if pos == 1 and pw == '近日':
            value = -1.80  # comma after a document-opening 'recently'

    if len(w) >= 2 and set(w) == {'·'}:
        value -= 1.06
    if w == '<|im_end|>':
        value += 0.067
    if w in {'</tool_call>', '<tool_response>'}:
        value += 0.104
    if w.lower() in {'will', 'would', 'can', 'could'}:
        value -= 0.02
    if w.lower() == 'shall':
        value += 0.12
    if w == '-':
        value -= 0.017
    if s.startswith('.') and w[1:] in PACKAGES:
        value -= 0.10
    if initial:
        han = bool(regex.search(r'\p{Script=Han}', w))
        value += 0.03 - 0.18 * han - 0.07 * s.startswith(' ')
        value -= 0.04 * (w.isascii() and w.isalpha())
        value += 0.07 * (bool(w) and w[0].isupper())
        if s == '<!':
            value = -2.25  # HTML declaration opener
        if s == '//\n':
            value = -2.13  # initial code-comment line
    if pos <= 2 and s == ' ' and blank:
        value -= 0.46 + 0.275 / math.sqrt(len(prev))
        if pos == 1 and prev == '   ':
            value = -1.63  # four-space indentation split into 3 + 1

    numeric = bool(w) and w[-1].isdigit()
    date_clause = date_clause and (w in {'月', '日'} or numeric or s.isspace())
    year = 0.85 * year + ('年' in s)
    japanese = 0.85 * japanese + bool(
        regex.search(r'[\p{Script=Hiragana}\p{Script=Katakana}]', s))
    return (doc, pos + 1, s, year, japanese, date_clause), float(value)

programs.haiku:
"""layers.1.mlp.down_proj:831 -- a weak, token-driven neuron with a few readable habits.

What the component is: one hidden unit of layer 1's MLP (index 831 of the 6144
intermediate neurons), read out through its down-projection column. Its activation is
almost always within a few hundredths of zero, with rare large swings of both signs. Most
of its variance is not explained by any short rule: the same token gives very different
values in different contexts, and no concept tried so far predicts the sign of the swings.

What this program does: it predicts a small, fixed value for a few word classes whose
average activation is clearly off zero, and 0 everywhere else.
  - Chinese date and time words (月, 日, 年, 时, 点, 上午, 下午, ...) and a few formal-notice
    words (报名, 条件, 为) run negative: they are where the strongest negative swings occur.
  - English modal words and common adverbs (will, can, just, very, ...) run slightly negative.
  - Chinese 会 / 應 / 应 / 不会 ("will / should") run positive.
  - Web and file-name tokens (.com, www, .log, .md, .txt) run positive.
  - Chat and markup tags (<|im_end|>, </tool_call>, <tool_response>) run slightly positive.
  - The first token after <|endoftext|> runs slightly positive.
  - The first token of a row (no preceding context) is predicted from its kind: Chinese
    characters negative, plain English words slightly negative, newlines and digits positive.
Each value is the mean activation measured on training text, so the program predicts the
average behaviour of each class rather than any single swing.
"""

READS = ()

DATE_NOTICE_WORDS = {
    "月", "日", "年", "时", "点", "分", "上午", "下午", "日晚", "日上午", "日下午",
    "时间", "为", "报名", "条件",
}
ENGLISH_MODALS = {
    "will", "can", "just", "very", "more", "than", "same", "only", "because", "under",
    "she", "void", "information", "may", "must", "should", "really", "often", "usually",
    "also", "simple", "special", "standard", "national", "government", "please",
}
CHINESE_WILL_SHOULD = {"会", "會", "应", "應", "不会"}
WEB_AND_FILE_TOKENS = {".com", "www", ".org", ".edu", ".net", ".gov", ".log", ".md", ".txt"}
MARKUP_TAGS = {"<|im_end|>", "</tool_call>", "<tool_response>", "<|im_start|>"}


def row_start_value(token):
    """First token of a row: no earlier context, so its kind alone sets the value."""
    if "\n" in token:
        return 0.16
    if token.strip().isdigit():
        return 0.09
    if any("一" <= ch <= "鿿" for ch in token):
        return -0.18
    if token.startswith(" ") and token.strip().isalpha():
        return -0.08
    return 0.0


def value_of(token, previous):
    """The mean activation of the class this token falls into, 0 outside every class."""
    word = token.strip()
    if word in DATE_NOTICE_WORDS:
        return -0.09
    if word in ENGLISH_MODALS:
        return -0.034
    if word in CHINESE_WILL_SHOULD:
        return 0.19
    if word in WEB_AND_FILE_TOKENS:
        return 0.076
    if token in MARKUP_TAGS:
        return 0.03
    if previous == "<|endoftext|>":
        return 0.048
    return 0.0


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    if len(prefix) == 1:
        return None, float(row_start_value(token))
    previous = prefix.token_strings[-2]
    return None, float(value_of(token, previous))
